package com.example

import com.example.ExamQuestionHelper.QSpec

internal object GeographyLiveExamClimateBank {
  private fun q(t: String, s: String, c: String, d1: String, d2: String, d3: String, e: String) =
    QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun climateQuestions(): List<QSpec> {
    val t = "කාලගුණය, දේශගුණය හා ගෝලීය දේශගුණ කලාප"
    return listOf(
      q(t, "යම් ස්ථානයක කෙටි කාලයක් තුළ වායුගෝලයේ පවතින උෂ්ණත්වය, වැසි හා සුළං ස්වභාවය හඳුන්වන්නේ කුමන නමකින්ද?",
        "කාලගුණය (Weather)", "දේශගුණය (Climate)", "සෘතු භේදය (Seasons)", "භූ විෂමතාව (Relief)",
        "උෂ්ණත්වය, වර්ෂාපතනය, සුළඟ හා ආර්ද්‍රතාව වැනි සාධකවල කෙටිකාලීන තත්ත්වය කාලගුණයයි."),
      q(t, "යම් ප්‍රදේශයක අවම වශයෙන් වසර 30–35 ක් පමණ දිගු කාලයක් තුළ පැවති කාලගුණික තත්ත්වයන්ගේ සාමාන්‍යය කුමක්ද?",
        "දේශගුණය (Climate)", "දෛනික කාලගුණ අනාවැකිය", "වායු පීඩන අනුක්‍රමණය", "උෂ්ණත්ව ප්‍රතිලෝමනය",
        "ලෝක කාලගුණ විද්‍යා සංවිධානය (WMO) අනුව වසර 30 ක සාමාන්‍යය දේශගුණය ලෙස ගණනය කෙරේ."),
      q(t, "වැසි, සුළං, අකුණු සහ වළාකුළු වැනි සියලු කාලගුණික සංසිද්ධි සිදුවන වායුගෝලයේ පහළම ස්තරය කුමක්ද?",
        "පරිවර්තී ගෝලය (Troposphere)", "අපවර්තී ගෝලය (Stratosphere)", "මධ්‍ය ගෝලය (Mesosphere)", "තාප ගෝලය (Thermosphere)",
        "පෘථිවි පෘෂ්ඨයේ සිට සාමාන්‍යයෙන් කි.මී. 8–18 ක් ඉහළට විහිදෙන Troposphere ස්තරයේ වායුගෝලීය ජල වාෂ්ප අඩංගු වේ."),
      q(t, "සූර්යයාගෙන් පැමිණෙන අහිතකර පාරජම්බුල (UV) කිරණ අවශෝෂණය කර ගන්නා ඕසෝන් ස්තරය පිහිටා ඇත්තේ කොහිද?",
        "අපවර්තී ගෝලය තුළය (Stratosphere)", "පරිවර්තී ගෝලය තුළය (Troposphere)", "මධ්‍ය ගෝලය තුළය (Mesosphere)", "බහිර් ගෝලය තුළය (Exosphere)",
        "අපවර්තී ගෝලයේ කි.මී. 15–35 අතර ඕසෝන් (O3) සාන්ද්‍රණය ඉහළ මට්ටමක පවතී."),
      q(t, "ජෙට් ගුවන් යානා දිගු දුර ගමන් සඳහා බහුලව භාවිත කරන, කැළඹීම් හා වළාකුළු අවම වායුගෝල ස්තරය කුමක්ද?",
        "අපවර්තී ගෝලයේ පහළ කොටස", "මධ්‍ය ගෝලයේ ඉහළ කොටස", "තාප ගෝලයේ අයන ස්තරය", "පරිවර්තී ගෝලයේ පහළ කොටස",
        "අපවර්තී ගෝලයේ කුණාටු හා සිරස් වායු ධාරා අඩු නිසා ගුවන් ගමන් ස්ථාවර වේ."),
      q(t, "අභ්‍යවකාශයේ සිට පෘථිවි වායුගෝලයට ඇතුළු වන උල්කාපාත (Meteors) බහුලව දැවී අළු වී යන ස්තරය කවරේද?",
        "මධ්‍ය ගෝලය (Mesosphere)", "පරිවර්තී ගෝලය (Troposphere)", "අපවර්තී ගෝලය (Stratosphere)", "බහිර් ගෝලය (Exosphere)",
        "මධ්‍ය ගෝලය වායුගෝලයේ සීතලම ස්තරය (-90°C පමණ) වන අතර උල්කාපාත දැවී යාම මෙහි සිදුවේ."),
      q(t, "රේඩියෝ තරංග පෘථිවියට පරාවර්තනය කර දුර සන්නිවේදනයට සහය වන ආරෝපිත අංශු සහිත ස්තරය කුමක්ද?",
        "තාප ගෝලයේ පිහිටි අයන ගෝලය", "පෘෂ්ඨයට ආසන්න පරිවර්තී ගෝලය", "ඕසෝන් ස්තරය ඇති අපවර්තී ගෝලය", "වායු අණු විරල බහිර් ගෝලය",
        "සූර්ය විකිරණ මගින් වායු අණු අයනීකරණය වීම නිසා Ionosphere ස්තරය ගොඩනැගේ."),
      q(t, "පෘථිවි වායුගෝලයේ වැඩිම ප්‍රතිශතයකින් (ආසන්න වශයෙන් 78%) අඩංගු වන ස්ථිර වායුව කුමක්ද?",
        "නයිට්‍රජන් වායුව (Nitrogen)", "ඔක්සිජන් වායුව (Oxygen)", "කාබන් ඩයොක්සයිඩ් වායුව", "ආගන් නිෂ්ක්‍රීය වායුව",
        "වියළි වාතයේ නයිට්‍රජන් ~78.08%, ඔක්සිජන් ~20.95%, ආගන් ~0.93% හා CO2 ~0.04% අඩංගු වේ."),
      q(t, "පරිවර්තී ගෝලය තුළ උන්නතාංශය මීටර් 1,000 කින් ඉහළ යන විට සාමාන්‍යයෙන් උෂ්ණත්වය කොපමණ අඩු වේද?",
        "සෙල්සියස් අංශක 6.5° කින් පමණ අඩු වේ", "සෙල්සියස් අංශක 1.0° කින් පමණ අඩු වේ", "සෙල්සියස් අංශක 20.0° කින් පමණ අඩු වේ", "සෙල්සියස් අංශක 15.0° කින් පමණ අඩු වේ",
        "Normal Lapse Rate අනුව මීටර් 1,000 කට 6.5°C කින් (මීටර් 165 කට 1°C) උෂ්ණත්වය අඩු වේ."),
      q(t, "කාලගුණ මධ්‍යස්ථානයක උෂ්ණත්වමාන තැන්පත් කර තබන සුදු පැහැති, ලූවර් සහිත ලී පෙට්ටිය කුමක්ද?",
        "සුදු පැහැති ස්ටීවන්සන් ආවරණය", "රසදිය බැරෝමීටර ආරක්ෂක පෙට්ටිය", "හයිග්‍රොමීටර ආරක්ෂක ලී කුටිය", "කාලගුණ රේඩාර් ආරක්ෂක පෙට්ටිය",
        "සෘජු හිරු එළියෙන් හා වර්ෂාවෙන් තොරව පොළොවෙන් මීටර් 1.2 ක් ඉහළින් වායු උෂ්ණත්වය මැනීමට මෙය යොදා ගනී."),
      q(t, "කාලගුණ මධ්‍යස්ථානයක ස්ටීවන්සන් ආවරණය සුදු පැහැයෙන් ආලේප කිරීමට ප්‍රධාන හේතුව කුමක්ද?",
        "සූර්ය තාපය පරාවර්තනය කර සත්‍ය සෙවණේ වායු උෂ්ණත්වය මැන ගැනීමටය", "කෘමීන් හා පක්ෂීන් ආවරණය තුළට ඇතුළු වීම වළක්වා ගැනීමටය", "රාත්‍රී කාලයේදී කාලගුණ නිරීක්ෂකයාට ආවරණය පහසුවෙන් හඳුනා ගැනීමටය", "අධික වර්ෂාවෙන් හා ආර්ද්‍රතාවෙන් ලී පෙට්ටිය ඉක්මනින් දිරාපත් නොවීමටය",
        "සුදු පැහැයට ඉහළ ඇල්බෙඩෝ අගයක් ඇති බැවින් අමතර තාප අවශෝෂණය වළකී."),
      q(t, "වායුගෝලීය පීඩනය (Atmospheric Pressure) මැනීම සඳහා කාලගුණ මධ්‍යස්ථානවල භාවිත කරන උපකරණය කුමක්ද?",
        "බැරෝමීටරය (Barometer)", "ඇනිමෝමීටරය (Anemometer)", "හයිග්‍රොමීටරය (Hygrometer)", "උපරිම-අවම උෂ්ණත්වමානය",
        "රසදිය හෝ නිර්ද්‍රව බැරෝමීටර මගින් මිලිබාර් (mb) හෝ හෙක්ටොපැස්කල් (hPa) වලින් පීඩනය මනී."),
      q(t, "සුළඟේ වේගය (Wind Speed) මැනීමට යොදා ගන්නා කැරකෙන කෝප්ප සහිත කාලගුණික උපකරණය කුමක්ද?",
        "ඇනිමෝමීටරය (Anemometer)", "සුළං දිශා දර්ශකය (Wind Vane)", "හයිග්‍රොමීටරය (Hygrometer)", "සූර්යාලෝක මානය (Recorder)",
        "ඇනිමෝමීටරය මගින් සුළඟේ වේගය පැ.කි.මී. හෝ නොට්ස් වලින් දක්වයි."),
      q(t, "සුළඟ හමන දිශාව (Wind Direction) නිවැරදිව හඳුනා ගැනීමට භාවිත කරන උපකරණය කුමක්ද?",
        "සුළං දිශා දර්ශකය (Wind Vane)", "කැරකෙන ඇනිමෝමීටරය (Anemometer)", "සම්මත වර්ෂා මානය (Rain Gauge)", "තෙත් හා වියළි බල්බ හයිග්‍රොමීටරය",
        "සුළං දිශා දර්ශකයේ ඊතලය සැමවිටම සුළඟ පැමිණෙන දිශාව වෙත හැරී පවතී."),
      q(t, "වාතයේ සාපේක්ෂ ආර්ද්‍රතාව (Relative Humidity) මැනීම සඳහා භාවිත කරන තෙත් හා වියළි බල්බ සහිත උපකරණය කුමක්ද?",
        "හයිග්‍රොමීටරය (Hygrometer)", "බැරෝමීටරය (Barometer)", "ඇනිමෝමීටරය (Anemometer)", "තර්මෝග්‍රැෆ් (Thermograph)",
        "තෙත් හා වියළි බල්බ උෂ්ණත්වමාන දෙකේ පාඨාංක අන්තරයෙන් වාතයේ ජල වාෂ්ප සංතෘප්තිය ගණනය කෙරේ."),
      q(t, "දිනකට ලැබෙන දීප්තිමත් සූර්යාලෝක පැය ගණන මැනීම සඳහා යොදා ගන්නා වීදුරු ගෝල සහිත උපකරණය කුමක්ද?",
        "කැම්බල්-ස්ටෝක්ස් සූර්යාලෝක මානය", "රේඩියෝසොන්ඩ් බැලූන් උපකරණය", "සම්මත වාෂ්පීකරණ මානය", "ඩිජිටල් භූ කම්පන මානය",
        "වීදුරු ගෝලය මගින් නාභිගත වන කිරණ කාඩ්පත පිළිස්සීමෙන් හිරු එළිය පැය ගණන සටහන් වේ."),
      q(t, "වර්ෂා මානය (Rain Gauge) ස්ථාපනය කිරීමේදී ගොඩනැගිලි හා ගස්වලින් ඈත්ව විවෘත ස්ථානයක තබන්නේ ඇයි?",
        "ගස් හෝ වහලවලින් ජලය වැටීම හා සුළං ආවරණ බලපෑම් වැළැක්වීමටය", "අධික සුළං හමන විට උපකරණය පොළොවෙන් ගැලවී යාම වැළැක්වීමටය", "කාලගුණ මධ්‍යස්ථානයේ සෙසු උපකරණවලින් වෙන්ව ආරක්ෂිතව තබා ගැනීමටය", "රැස්වන වර්ෂා ජලය ඉක්මනින් වාෂ්ප වී යාම වේගවත් කර ගැනීමටය",
        "බාධකයේ උස මෙන් දෙගුණයකවත් දුරින් තැබීම නිවැරදි මිනුම් ලබා ගැනීමේ රීතියයි."),
      q(t, "සමක ප්‍රදේශවල සහ ශ්‍රී ලංකාවේ අන්තර් මෝසම් කාලවලදී දහවල් අධික උණුසුම නිසා ඇතිවන වර්ෂාපතන වර්ගය කුමක්ද?",
        "සංවහන වර්ෂාව (Convectional Rainfall)", "භූ විෂමතා වර්ෂාව (Orographic Rainfall)", "වාතාග්‍ර / පෙරමුණු වර්ෂාව (Frontal Rainfall)", "නිවර්තන වාසුළි වර්ෂාව (Cyclonic Rainfall)",
        "රත් වූ තෙත් වාතය සිරස්ව ඉහළ නැග සිසිල් වී සවස් කාලයේ ගිගුරුම් සහිත වැසි ලබා දෙයි."),
      q(t, "තෙත් වායු ධාරාවක් කඳු වැටියක ගැටී ඉහළ නැගීමෙන් සුළං මුහුණත බෑවුමට ලැබෙන වර්ෂාව කුමක්ද?",
        "භූ විෂමතා / කඳු ආශ්‍රිත වර්ෂාව (Orographic Rainfall)", "සංවහන / උෂ්ණත්ව වර්ෂාව (Convectional Rainfall)", "පෙරමුණු / වාතාග්‍ර වර්ෂාව (Frontal Rainfall)", "ධ්‍රැවීය හිම කැට වර්ෂාව (Hail Precipitation)",
        "ශ්‍රී ලංකාවේ නිරිතදිග මෝසම මගින් මධ්‍යම කඳුකරයේ බටහිර බෑවුම්වලට අධික භූ විෂමතා වර්ෂාව ලැබේ."),
      q(t, "කඳු වැටියක සුළඟට ප්‍රතිවිරුද්ධ පැත්තේ පිහිටි, වියළි වාතය පහළ බැසීම නිසා වියළි කාලගුණයක් පවතින ප්‍රදේශය කුමක්ද?",
        "වැසි මුවාව (Rain Shadow Area)", "සමෝච්ච බෑවුම (Contour Slope)", "වාතාග්‍ර කලාපය (Frontal Zone)", "සංවහන කලාපය (Convection Zone)",
        "මෝසම් සුළං කඳු වැටි පසු කර පහළ බසින විට සම්පීඩනයෙන් රත් වී වියළි බව ඇති කරයි."),
      q(t, "උණුසුම් වායු ස්කන්ධයක් සහ සීතල වායු ස්කන්ධයක් එකිනෙක හමුවන සීමාවේදී ඇතිවන වර්ෂා වර්ගය කුමක්ද?",
        "පෙරමුණු / වාතාග්‍ර වර්ෂාව (Frontal Rainfall)", "භූ විෂමතා / කඳු ආශ්‍රිත වර්ෂාව (Orographic Rainfall)", "සංවහන / තාප වර්ෂාව (Convectional Rainfall)", "මුහුදු සුළං ආශ්‍රිත වෙරළ වර්ෂාව (Coastal Rainfall)",
        "සමශීතෝෂ්ණ කලාපවල උණුසුම් හා සීතල වායු ස්කන්ධ ගැටීමේදී සැහැල්ලු උණුසුම් වාතය ඉහළ නැග වැසි ඇති කරයි."),
      q(t, "අහසේ සිරස්ව ඉහළට වැඩෙන, ගිගුරුම් සහිත අකුණු වැසි ගෙනෙන දැවැන්ත වළාකුළු වර්ගය කුමක්ද?",
        "කැටි වැහි වළාකුළු (Cumulonimbus)", "කෙඳි වළාකුළු (Cirrus)", "ස්තර වළාකුළු (Stratus)", "උස් කෙඳි වළාකුළු (Cirrocumulus)",
        "Cumulonimbus වළාකුළු කි.මී. 12–15 ක් දක්වා ඉහළ නැග දැඩි වර්ෂාව, අකුණු සහ හිම කැට ඇති කරයි."),
      q(t, "ඉතා ඉහළ උන්නතාංශයේ (මීටර් 6,000 ට ඉහළින්) පිහාටු හෝ කෙඳි ආකාරයෙන් පෙනෙන අයිස් ස්ඵටිකමය වළාකුළු මොනවාද?",
        "සිරස් / කෙඳි වළාකුළු (Cirrus)", "නිම්බොස්ට්‍රේටස් වළාකුළු (Nimbostratus)", "කියුමියුලස් වළාකුළු (Cumulus)", "ඇල්ටොස්ට්‍රේටස් වළාකුළු (Altostratus)",
        "Cirrus වළාකුළු වර්ෂාව නොදෙන නමුත් ඉදිරියේදී කාලගුණ වෙනසක් සිදුවිය හැකි බව හඟවයි."),
      q(t, "මුළු අහසම අළු පැහැති ඝන තට්ටුවකින් වසාගෙන නොනවතින සැහැල්ලු හෝ මධ්‍යස්ථ වැසි ලබා දෙන පහළ වළාකුළු වර්ගය කුමක්ද?",
        "නිම්බොස්ට්‍රේටස් (Nimbostratus)", "සිරස් වළාකුළු (Cirrus)", "කියුමියුලස් වළාකුළු (Cumulus)", "සිරෝස්ට්‍රේටස් (Cirrostratus)",
        "මෝසම් කාලයේදී දිගු වේලාවක් පවතින වැසි සඳහා Nimbostratus වළාකුළු ප්‍රධාන වේ."),
      q(t, "සමකයේ සිට 5°N හා 5°S අතර පිහිටි, සුළං ඉතා මන්දගාමී හා වාතය ඉහළ නගින අඩු පීඩන කලාපය හඳුන්වන්නේ කෙසේද?",
        "අන්තර් නිවර්තන අභිසාරී කලාපය (ITCZ / Doldrums)", "උප නිවර්තන අශ්ව අක්ෂාංශ (Horse Latitudes)", "දක්ෂිණ ඝෝෂාකාරී හතළිහ (Roaring Forties)", "ධ්‍රැවීය අධි පීඩන කලාපය (Polar High)",
        "උතුරු හා දකුණු වෙළඳ සුළං හමුවන ITCZ කලාපය සංවහන වැසි සඳහා ප්‍රසිද්ධය."),
      q(t, "30°N සහ 30°S අක්ෂාංශ ආසන්නයේ වාතය පහළට බැසීම නිසා වියළි කාන්තාර බිහිවීමට දායක වන පීඩන කලාපය කුමක්ද?",
        "උප නිවර්තන අධි පීඩන කලාපය (Horse Latitudes)", "සමක අඩු පීඩන කලාපය (Equatorial Low)", "උප ධ්‍රැවීය අඩු පීඩන කලාපය (Subpolar Low)", "නිවර්තන මෝසම් අගාධ කලාපය (Monsoon Trough)",
        "සහාරා, කලහාරි සහ ඕස්ට්‍රේලියානු කාන්තාර බහුලව 20°–30° අක්ෂාංශ අතර අධි පීඩන කලාපයේ පිහිටයි."),
      q(t, "උප නිවර්තන අධි පීඩන කලාපයේ සිට සමක අඩු පීඩන කලාපය දෙසට හමන නියත ග්‍රහලෝක සුළං මොනවාද?",
        "වෙළඳ සුළං (Trade Winds)", "බටහිර සුළං (Westerlies)", "ධ්‍රැවීය නැගෙනහිර සුළං (Polar Easterlies)", "දෛනික මුහුදු සුළං (Sea Breezes)",
        "කොරියෝලිස් බලය නිසා උතුරු අර්ධගෝලයේදී ඊසාන වෙළඳ සුළං ලෙසත් දකුණේදී ගිනිකොන වෙළඳ සුළං ලෙසත් හමයි."),
      q(t, "පෘථිවියේ භ්‍රමණය නිසා හමන සුළං උතුරු අර්ධගෝලයේදී දකුණටත් දකුණු අර්ධගෝලයේදී වමටත් හැරවීමේ ආචරණය කුමක්ද?",
        "කොරියෝලිස් ආචරණය (Coriolis Effect)", "හරිතාගාර ආචරණය (Greenhouse Effect)", "ඇල්බෙඩෝ ආචරණය (Albedo Effect)", "තාප ප්‍රතිලෝමනය (Temperature Inversion)",
        "ප්‍රංශ විද්‍යාඥ Gaspard-Gustave de Coriolis විසින් පැහැදිලි කළ මෙම බලය සමකයේදී ශුන්‍ය වේ."),
      q(t, "දක්ෂිණ අර්ධගෝලයේ 40°S අක්ෂාංශ ආසන්නයේ ගොඩබිම් බාධක නොමැති නිසා ඉතා වේගයෙන් හමන බටහිර සුළං හඳුන්වන නම කුමක්ද?",
        "ගිගුරුම් සහිත හතළිහ (Roaring Forties)", "ඊසාන වෙළඳ සුළං (Northeast Trades)", "සමක ඩෝල්ඩ්‍රම්ස් (Equatorial Doldrums)", "සහාරා හර්මැටන් සුළං (Harmattan Winds)",
        "40°S හි Roaring Forties, 50°S හි Furious Fifties සහ 60°S හි Shrieking Sixties ලෙස හැඳින්වේ."),
      q(t, "දිවා කාලයේදී ගොඩබිම සාගරයට වඩා ඉක්මනින් රත් වී ගොඩබිම මත අඩු පීඩනයක් ඇති වීම නිසා හමන සුළඟ කුමක්ද?",
        "මුහුදු සුළඟ (Sea Breeze)", "ගොඩබිම් සුළඟ (Land Breeze)", "නිම්න සුළඟ (Valley Breeze)", "ධ්‍රැවීය සුළඟ (Polar Wind)",
        "දහවල් කාලයේදී සිසිල් සාගරයේ සිට උණුසුම් ගොඩබිම දෙසට මුහුදු සුළං හමා එයි."),
      q(t, "රාත්‍රී කාලයේදී ගොඩබිම ඉක්මනින් සිසිල් වීම නිසා ගොඩබිමේ සිට උණුසුම් සාගරය දෙසට හමන සුළඟ කුමක්ද?",
        "ගොඩබිම් සුළඟ (Land Breeze)", "මුහුදු සුළඟ (Sea Breeze)", "චිනූක් සුළඟ (Chinook Wind)", "මෝසම් සුළඟ (Monsoon Wind)",
        "රාත්‍රියේදී සාගරය සෙමින් සිසිල් වන බැවින් සාගරය මත සාපේක්ෂ අඩු පීඩනයක් පවතී."),
      q(t, "'මෝසම්' (Monsoon) යන වචනය බිඳී ආ අරාබි 'මව්සිම්' (Mausim) යන්නෙහි අර්ථය කුමක්ද?",
        "සෘතුව යන්නයි (Season)", "කුණාටුව යන්නයි (Storm)", "වර්ෂාව යන්නයි (Rainfall)", "කාන්තාරය යන්නයි (Desert)",
        "සෘතු අනුව සම්පූර්ණයෙන්ම දිශාව මාරු කර හමන සුළං පද්ධති මෝසම් සුළං නම් වේ."),
      q(t, "ශ්‍රී ලංකාවට මැයි සිට සැප්තැම්බර් දක්වා කාලය තුළ නිරිතදිග මෝසම හමා එන්නේ ඇයි?",
        "ග්‍රීෂ්ම සෘතුවේදී මධ්‍යම ආසියානු හා ඉන්දියානු ගොඩබිමේ ඇතිවන අඩු පීඩන කලාපය ආකර්ෂණය වීමෙන්", "උත්තර ධ්‍රැවයේ ග්ලැසියර හා හිම තට්ටු වේගයෙන් දියවී යාමෙන් සුළං දිශාව මාරු වීමෙන්", "වසරකට දෙවරක් සිදුවන සූර්යග්‍රහණ නිසා වායුගෝලීය පීඩන කලාප සම්පූර්ණයෙන් වෙනස් වීමෙන්", "බටහිර ශාන්තිකර සාගරයේ හටගන්නා ප්‍රබල නිවර්තන සුළි කුණාටු ඉන්දියන් සාගරයට පැමිණීමෙන්",
        "දකුණු ඉන්දියන් සාගරයේ ගිනිකොන වෙළඳ සුළං සමකය පසු කර කොරියෝලිස් බලයෙන් දකුණට හැරී නිරිතදිග මෝසම බවට පත්වේ."),
      q(t, "ශ්‍රී ලංකාවට දෙසැම්බර් සිට පෙබරවාරි දක්වා ඊසානදිග මෝසම් වර්ෂාව ගෙන එන සුළං හමා එන්නේ කුමන ප්‍රදේශයේ සිටද?",
        "ආසියානු මහාද්වීපයේ සීතල අධි පීඩන කලාපයේ සිට බෙංගාල බොක්ක හරහාය", "අප්‍රිකානු මහාද්වීපයේ සහාරා කලාපයේ සිට අරාබි මුහුද හරහාය", "දකුණු ඉන්දියන් සාගරයේ මැඩගස්කර් දූපත ආශ්‍රිත ප්‍රදේශයේ සිටය", "මහා ඕස්ට්‍රේලියානු කාන්තාරයේ සිට නැගෙනහිර පැසිෆික් සාගරය හරහාය",
        "බෙංගාල බොක්ක හරහා පැමිණීමේදී තෙතමනය උරාගෙන ශ්‍රී ලංකාවේ උතුරු හා නැගෙනහිරට වැසි ලබා දෙයි."),
      q(t, "ශ්‍රී ලංකාවේ නිරිතදිග මෝසම් කාලයේදී මධ්‍යම කඳුකරයේ වැසි මුවාවේ පිහිටි නැගෙනහිර බෑවුම්වලට හමන උණුසුම් වියළි සුළඟ කුමක්ද?",
        "කච්චාන් සුළඟ (Kachchan Wind)", "මිස්ට්‍රල් සුළඟ (Mistral Wind)", "හර්මැටන් සුළඟ (Harmattan Wind)", "බෝරා සුළඟ (Bora Wind)",
        "බදුල්ල, අම්පාර සහ මඩකලපුව ප්‍රදේශවලට ජූනි–අගෝස්තු අතර හමන වියළි සුළඟ කච්චාන් නම් වේ."),
      q(t, "උතුරු ඇමරිකාවේ රොකී කඳු වැටියේ නැගෙනහිර බෑවුම් දිගේ පහළ බසිමින් ශීත හිම ඉක්මනින් දිය කරන උණුසුම් සුළඟ කුමක්ද?",
        "චිනූක් සුළඟ (Chinook Wind)", "මිස්ට්‍රල් සුළඟ (Mistral Wind)", "සිරොක්කෝ සුළඟ (Sirocco Wind)", "පැම්පෙරෝ සුළඟ (Pampero Wind)",
        "ඇල්ප්ස් කඳුකරයේ ෆෝන් (Föhn) සුළඟට සමාන මෙම සුළඟ රොකී කඳු පාමුල උෂ්ණත්වය පැය කිහිපයකින් ඉහළ නංවයි."),
      q(t, "බටහිර අප්‍රිකාවේ සහාරා කාන්තාරයේ සිට ගිනියා වෙරළ දෙසට හමන අතිශය වියළි හා දූවිලි සහිත සුළඟ කුමක්ද?",
        "හර්මැටන් සුළඟ (Harmattan Wind)", "බ්ලිසාර්ඩ් හිම කුණාටුව (Blizzard)", "ටෝනේඩෝ සුළි සුළඟ (Tornado)", "ලෙවැන්ටර් සුළඟ (Levanter Wind)",
        "තෙත් වෙරළබඩ උණුසුම් ආර්ද්‍රතාව අඩු කරන බැවින් එය 'The Doctor' ලෙසද හැඳින්වේ."),
      q(t, "උතුරු අප්‍රිකාවේ සිට මධ්‍යධරණී මුහුද හරහා දකුණු යුරෝපය දෙසට හමන උණුසුම් දූවිලි සහිත සුළඟ කුමක්ද?",
        "සිරොක්කෝ සුළඟ (Sirocco Wind)", "මිස්ට්‍රල් සුළඟ (Mistral Wind)", "බෝරා සුළඟ (Bora Wind)", "චිනූක් සුළඟ (Chinook Wind)",
        "සිරොක්කෝ සුළඟ මධ්‍යධරණී මුහුද හරහා තෙතමනය උරාගෙන ඉතාලියට 'රුධිර වැසි' (රතු දූවිලි වැසි) ගෙන එයි."),
      q(t, "ශ්‍රී ලංකාවේ නිරිතදිග ප්‍රදේශයට වැඩිම වාර්ෂික වර්ෂාපතනයක් (මි.මී. 5,000 ට අධික) වාර්තා වී ඇති ස්ථානයක් වන්නේ කුමක්ද?",
        "වටවල හා මාලිබොඩ ප්‍රදේශ", "හම්බන්තොට හා තිස්සමහාරාම ප්‍රදේශ", "මන්නාරම හා පුත්තලම ප්‍රදේශ", "මඩකලපුව හා ත්‍රිකුණාමල ප්‍රදේශ",
        "නුවරඑළිය දිස්ත්‍රික්කයේ වටවල හා කෑගල්ල දිස්ත්‍රික්කයේ මාලිබොඩ ප්‍රදේශ අධික වැසි ලබයි."),
      q(t, "ශ්‍රී ලංකාවේ අඩුම වාර්ෂික වර්ෂාපතනයක් (මි.මී. 1,000 ට අඩු) ලැබෙන අර්ධ ශුෂ්ක කලාප දෙක මොනවාද?",
        "මන්නාරම-යාපනය සහ හම්බන්තොට-යාල ප්‍රදේශ", "රත්නපුර-බලංගොඩ සහ කළුතර-මතුගම ප්‍රදේශ", "මහනුවර-පේරාදෙණිය සහ මාතලේ-දඹුල්ල ප්‍රදේශ", "ගාල්ල-හික්කඩුව සහ මාතර-වැලිගම ප්‍රදේශ",
        "මෝසම් සුළං දෙකම මෙම කලාප හරහා වියළිව හෝ සමාන්තරව ගමන් කිරීම ඊට හේතුවයි."),
      q(t, "මධ්‍යධරණී දේශගුණ කලාපයේ (Mediterranean Climate) ඇති සුවිශේෂීම කාලගුණික ලක්ෂණය කුමක්ද?",
        "උණුසුම් වියළි ග්‍රීෂ්ම සෘතුවක් සහ සෞම්‍ය තෙත් ශීත සෘතුවක් පැවතීම", "වසර පුරාම සෑම දිනකම සවස් කාලයේ නොනවතින සංවහන වැසි ලැබීම", "වසරේ සෑම මාසයකම අධික හිම පතනය සහිත අයිස් දේශගුණයක් පැවතීම", "ග්‍රීෂ්ම සෘතුවේදී පමණක් මෝසම් වැසි ලැබී ශීත සෘතුව වියළිව පැවතීම",
        "ශීත සෘතුවේදී බටහිර සුළං මගින් මධ්‍යධරණී ප්‍රදේශයට වැසි ලැබෙන අතර ග්‍රීෂ්මයේදී වෙළඳ සුළං යටතේ වියළි වේ."),
      q(t, "සමක වැසි වනාන්තර දේශගුණයේ (Tropical Rainforest) ප්‍රධාන ලක්ෂණය කුමක්ද?",
        "වසර පුරා අධික උෂ්ණත්වය සහ නිරන්තර සංවහන වර්ෂාපතනය", "වසරකට මාස හයක් පවතින දිගු වියළි සෘතුවක් තිබීම", "වසන්ත ග්‍රීෂ්ම ශරත් හා ශීත ලෙස සෘතු හතරක් පැහැදිලිව වෙන්වීම", "වාර්ෂික උෂ්ණත්ව අන්තරය සෙල්සියස් අංශක 30° ඉක්මවා පැවතීම",
        "ඇමසන්, කොංගෝ සහ මැලේසියානු දූපත් සමූහය මෙම කලාපයට අයත් වේ."),
      q(t, "නිවර්තන සැවානා දේශගුණය (Tropical Savanna) සමක දේශගුණයෙන් ප්‍රධාන වශයෙන් වෙනස් වන්නේ කෙසේද?",
        "පැහැදිලි තෙත් සෘතුවක් සහ පැහැදිලි වියළි සෘතුවක් පැවතීමෙනි", "වසර පුරාම අධික හිම පතනයක් හා තුහින පැවතීමෙනි", "ග්‍රහලෝක සුළං පද්ධති කිසිවක් හමා නොයාමෙනි", "වසරේ සෑම මාසයකම උෂ්ණත්වය 0°C ට වඩා අඩු වීමෙනි",
        "උස තෘණ සහ විසිරුණු කුඩා ගස් (Acacia, Baobab) සහිත තණබිම් සැවානා කලාපයේ ලක්ෂණයයි."),
      q(t, "වොල්ඩිමීර් කෝපන්ගේ (Köppen) දේශගුණ වර්ගීකරණයේදී 'B' අකුරෙන් නිරූපණය වන දේශගුණ කාණ්ඩය කුමක්ද?",
        "ශුෂ්ක හා අර්ධ ශුෂ්ක දේශගුණය", "නිවර්තන තෙත් වැසි වනාන්තර දේශගුණය", "ධ්‍රැවීය හිම සහ අයිස් කලාප දේශගුණය", "සමශීතෝෂ්ණ සෞම්‍ය කලාපීය දේශගුණය",
        "වාෂ්පීකරණ විභවය වර්ෂාපතනයට වඩා වැඩි කාන්තාර (BW) හා ස්ටෙප් (BS) ප්‍රදේශ 'B' කාණ්ඩයට වැටේ."),
      q(t, "විශාල මහාද්වීප අභ්‍යන්තරයේ පිහිටි ගොබි (Gobi) සහ ටක්ලමකන් කාන්තාර ඇතිවීමට බලපෑ ප්‍රධාන හේතුව කුමක්ද?",
        "සාගරවලින් අධික දුරකින් පිහිටීම හා උස කඳු වැටි මගින් තෙතමනය අවහිර කිරීම", "වෙරළට සමාන්තරව ගලා යන සීතල සාගර දියවැල් මගින් වාෂ්පීකරණය අඩු කිරීම", "පෘථිවි කබොලේ සිදුවන අධික ගිනිකඳු ක්‍රියාකාරිත්වය හේතුවෙන් පස උණුසුම් වීම", "භූගත ජල ස්තරයේ පවතින ඉහළ ලවණතාව නිසා ශාක වැඩීම සම්පූර්ණයෙන් නැවතීම",
        "හිමාලය හා අනෙකුත් කඳු වැටි මෝසම් තෙතමනය මධ්‍ය ආසියාවට යාම වළක්වයි."),
      q(t, "නැමීබ් (Namib) සහ ඇටකාමා (Atacama) කාන්තාර මුහුදු වෙරළ ආසන්නයේ පිහිටා තිබුණද අතිශයින් වියළි වන්නේ ඇයි?",
        "වෙරළට සමාන්තරව ගලා යන සීතල සාගර දියවැල් වායු ඉහළ නැගීම වළක්වන බැවිනි", "වෙරළට සමාන්තරව ගලා යන උණුසුම් දියවැල් නිසා වළාකුළු සෑදීම වළකින බැවිනි", "වෙරළබඩ කලාපයේ පැවති ස්වාභාවික වනාන්තර මිනිසුන් විසින් කපා දැමූ බැවිනි", "සාගර පතුලේ නිරන්තරයෙන් සිදුවන ප්‍රබල භූ කම්පන නිසා සුළං දිශාව වෙනස් වන බැවිනි",
        "සීතල ජලය මත වාතය සිසිල් වී ස්ථාවර වන බැවින් වැසි වළාකුළු නොසෑදී මීදුම පමණක් ඇති වේ."),
      q(t, "උතුරු ධ්‍රැවය ආසන්නයේ පිහිටි, පස යට නිත්‍ය තුහින (Permafrost) ස්තරයක් ඇති දේශගුණ කලාපය කුමක්ද?",
        "ටුන්ඩ්‍රා දේශගුණ කලාපය (Tundra)", "ටයිගා කේතුධර වනාන්තර කලාපය (Taiga)", "මධ්‍යධරණී දේශගුණ කලාපය (Mediterranean)", "නිවර්තන සැවානා තණබිම් කලාපය (Savanna)",
        "ටුන්ඩ්‍රා කලාපයේ උණුසුම්ම මාසයේ සාමාන්‍ය උෂ්ණත්වය 0°C – 10°C අතර පවතින අතර පාසි හා ලයිකන වැවේ."),
      q(t, "උතුරු අර්ධගෝලයේ උප ආක්ටික් කලාපයේ පිහිටි, කේතුධර වනාන්තර (Coniferous Forests) බහුල ජෛව පද්ධතිය කුමක්ද?",
        "ටයිගා හෙවත් බෝරියල් වනාන්තර කලාපය", "නිවර්තන සැවානා තණබිම් කලාපය", "සමක සදාහරිත වැසි වනාන්තර කලාපය", "මධ්‍යධරණී චැපරල් ලඳු කැලෑ කලාපය",
        "පයින්, ස්පෘස් සහ ෆර් වැනි ඉදිකටු පත්‍ර සහිත ගස් රුසියාව හා කැනඩාව පුරා ටයිගා වනාන්තර සාදයි."),
      q(t, "ස්වභාවික හරිතාගාර ආචරණය (Natural Greenhouse Effect) පෘථිවියේ ජීවය පැවතීමට අත්‍යවශ්‍ය වන්නේ ඇයි?",
        "පෘථිවියෙන් පිටවන අධෝරක්ත තාපය රඳවාගෙන සාමාන්‍ය උෂ්ණත්වය +15°C මට්ටමේ පවත්වා ගැනීම නිසාය", "සූර්යයාගෙන් පැමිණෙන අහිතකර පාරජම්බුල කිරණ වායුගෝලයේ ඉහළ ස්තරවලදී නිපදවන නිසාය", "සමකයේ සිට ධ්‍රැව දක්වා හමා යන සියලු ග්‍රහලෝක සුළං සම්පූර්ණයෙන්ම නවතා දමන නිසාය", "වායුගෝලයේ ඇති නයිට්‍රජන් වායුව ශාකවල ප්‍රභාසංශ්ලේෂණය සඳහා ඔක්සිජන් බවට හරවන නිසාය",
        "හරිතාගාර ආචරණය නොතිබුණේ නම් පෘථිවියේ සාමාන්‍ය උෂ්ණත්වය -18°C පමණ වනු ඇත."),
      q(t, "මිනිස් ක්‍රියාකාරකම් නිසා වර්ධනය වන ගෝලීය උණුසුම් වීමට ප්‍රධාන වශයෙන්ම දායක වන හරිතාගාර වායු මොනවාද?",
        "කාබන් ඩයොක්සයිඩ්, මීතේන් සහ නයිට්‍රස් ඔක්සයිඩ්", "නයිට්‍රජන්, ඔක්සිජන් සහ ආගන් වායු", "හීලියම්, නියෝන් සහ ක්‍රිප්ටන් වායු", "හයිඩ්‍රජන්, ඔක්සිජන් සහ ක්ලෝරීන් වායු",
        "ෆොසිල ඉන්ධන දහනය, වන විනාශය හා කෘෂිකර්මාන්තය මගින් CO2 සහ CH4 ප්‍රමාණය ඉහළ යයි."),
      q(t, "පෘථිවි පෘෂ්ඨයේ සූර්ය විකිරණ පරාවර්තනය කිරීමේ හැකියාව හඳුන්වන 'ඇල්බෙඩෝ' (Albedo) අගය ඉහළම පෘෂ්ඨය කුමක්ද?",
        "නැවුම් සුදු හිම සහ අයිස් පෘෂ්ඨය", "තද නිල් පැහැති ගැඹුරු සාගර ජලය", "සදාහරිත නිවර්තන වැසි වනාන්තර වියන", "කළු තාර දැමූ නාගරික මහාමාර්ග",
        "හිම දියවී යාමේදී ඇල්බෙඩෝ අගය අඩු වී සාගරය හෝ පොළොව වැඩි තාපයක් උරා ගැනීම Ice-Albedo Feedback නම් වේ."),
      q(t, "'එල් නිනෝ' (El Niño) සංසිද්ධිය සිදුවන විට නිරක්ෂීය පැසිෆික් සාගරයේ කුමන වෙනසක් සිදුවේද?",
        "මධ්‍යම හා නැගෙනහිර පැසිෆික් සාගරයේ මතුපිට ජල උෂ්ණත්වය අසාමාන්‍ය ලෙස ඉහළ යාම", "උතුරු හා දකුණු අත්ලාන්තික් සාගරය සම්පූර්ණයෙන්ම අයිස් බවට පත්වී මිදී යාම", "පේරු වෙරළ ආසන්නයේ සීතල සාගර ජලය ඉහළට ගලා ඒම වේගවත් ලෙස වැඩි වීම", "සමක රේඛාව ආසන්නයේ විශාල හිම කඳු හා ග්ලැසියර අලුතින් නිර්මාණය වීම",
        "වෙළඳ සුළං දුර්වල වීම නිසා උණුසුම් ජලය දකුණු ඇමරිකා වෙරළ දෙසට ගලා ගොස් ගෝලීය කාලගුණය වෙනස් කරයි."),
      q(t, "එල් නිනෝ තත්ත්වය හේතුවෙන් දකුණු ආසියාවට, ඕස්ට්‍රේලියාවට සහ ඉන්දුනීසියාවට බහුලව ඇතිවිය හැකි බලපෑම කුමක්ද?",
        "මෝසම් වර්ෂාපතනය දුර්වල වී නියඟ හා ලැව්ගිනි අවදානම ඉහළ යාම", "වසර පුරාම අධික හිම කුණාටු හා දැඩි ශීතල කාලගුණයක් ඇති වීම", "සදාහරිත වනාන්තර සියල්ල ටුන්ඩ්‍රා දේශගුණ කලාප බවට පරිවර්තනය වීම", "සාගර පතුලේ භූ කම්පන හටගෙන දැවැන්ත සුනාමි රළ වෙරළට කඩා වැදීම",
        "එල් නිනෝ කාලවලදී බටහිර පැසිෆික් සහ ඉන්දියන් සාගර කලාපවල වර්ෂාව අඩු වන අතර පේරු වෙරළට ගංවතුර ඇති වේ."),
      q(t, "නිවර්තන සුළි සුළං (Tropical Cyclones) උත්පාදනය වීම සඳහා අවශ්‍ය අවම සාගර මතුපිට ජල උෂ්ණත්වය කොපමණද?",
        "සෙල්සියස් අංශක 26.5° හෝ ඊට වැඩි උෂ්ණත්වයක්", "සෙල්සියස් අංශක 5.0° හෝ ඊට අඩු උෂ්ණත්වයක්", "සෙල්සියස් අංශක 10.0° පමණ වන මධ්‍යස්ථ උෂ්ණත්වයක්", "සෙල්සියස් අංශක 50.0° ඉක්මවන අධික උෂ්ණත්වයක්",
        "උණුසුම් සාගර ජලයෙන් ලැබෙන ගුප්ත තාපය සුළි සුළඟක ප්‍රධාන ශක්ති ප්‍රභවයයි."),
      q(t, "නිවර්තන සුළි සුළඟක් (Cyclone) සමකයේ සිට 5° කලාපය තුළ (0°–5°) කිසිදා හට නොගන්නේ ඇයි?",
        "සමකය ආසන්නයේ කොරියෝලිස් බලය ඉතා දුර්වල හෝ ශුන්‍ය වන බැවින් භ්‍රමණයක් ඇති නොවන නිසාය", "සමකය ආසන්න සාගර ජලය ධ්‍රැවීය සාගර ජලයට වඩා අතිශයින් සීතල මට්ටමක පවතින නිසාය", "සමක කලාපයේ වායුගෝලය තුළ ජල වාෂ්ප හා වායු ස්කන්ධ කිසිසේත් නොපවතින නිසාය", "සමක රේඛාව දිගේ පිහිටි උස කඳු වැටි මගින් සුළං හමා යාම සම්පූර්ණයෙන් අවහිර කරන නිසාය",
        "වාතය අඩු පීඩන මධ්‍යය වටා කැරකැවීමට ප්‍රමාණවත් කොරියෝලිස් බලයක් අවශ්‍ය වේ."),
      q(t, "සුළි සුළඟක මධ්‍යයේ පිහිටි, සුළං සන්සුන් හා අහස පැහැදිලිව පවතින කලාපය හඳුන්වන්නේ කුමන නමකින්ද?",
        "සුළි සුළඟේ ඇස (Eye of the Cyclone)", "ඇසේ පවුර (Eye Wall)", "සර්පිලාකාර වළා පටිය (Spiral Rainband)", "පෙරමුණු අගාධය (Frontal Trough)",
        "Eye Wall කලාපයේ දරුණුම සුළං හා වැසි පවතින නමුත් ඇස තුළ වාතය සෙමින් පහළ බසී."),
      q(t, "උතුරු අර්ධගෝලයේ අඩු පීඩන මධ්‍යස්ථානයක් (Cyclone) වටා සුළං භ්‍රමණය වන දිශාව කුමක්ද?",
        "ඔරලෝසු කටුවට ප්‍රතිවිරුද්ධ දිශාවටය (Anticlockwise)", "ඔරලෝසු කටුවේ ගමන් දිශාවටය (Clockwise)", "සෘජුව උතුරු දිශාවට පමණක් ගමන් කරයි", "ඉහළ සිට පහළට සිරස්ව පමණක් ගමන් කරයි",
        "දකුණු අර්ධගෝලයේදී සුළි සුළං ඔරලෝසු කටුවේ දිශාවට (Clockwise) භ්‍රමණය වේ."),
      q(t, "නාගරික ප්‍රදේශ අවට ග්‍රාමීය ප්‍රදේශවලට වඩා උණුසුම් වීමේ 'නාගරික තාප දූපත' (Urban Heat Island) සංසිද්ධිය ඇති වන්නේ ඇයි?",
        "කොන්ක්‍රීට් පෘෂ්ඨ තාපය රඳවා ගැනීම, ගස් අඩුවීම සහ වාහන තාප විමෝචනය නිසාය", "නාගරික ප්‍රදේශවලට ග්‍රාමීය ප්‍රදේශවලට වඩා සංවහන වර්ෂාපතනය අධික ලෙස ලැබෙන නිසාය", "ගෝලීය මුහුදු මට්ටම ඉහළ යාම හේතුවෙන් නගර අසල උණුසුම් රළ ගැසීම නිසාය", "ධ්‍රැවීය ප්‍රදේශවල සිට හමා එන සීතල සුළං නගර මධ්‍යයේදී උණුසුම් වන නිසාය",
        "හරිත අවකාශ හා ජලාශ වැඩි කිරීමෙන් නාගරික තාප දූපත් බලපෑම අවම කළ හැක."),
      q(t, "ඕසෝන් ස්තරය ක්ෂය වීමට ප්‍රධාන වශයෙන්ම හේතු වූ මිනිසා විසින් නිපදවූ රසායනික සංයෝග මොනවාද?",
        "ක්ලෝරෝෆ්ලෝරෝකාබන් (CFCs) සහ හේලෝන් වායු", "ඔක්සිජන් වායුව සහ හීලියම් වායුව", "නයිට්‍රජන් වායුව සහ ආගන් වායුව", "කැල්සියම් කාබනේට් සහ සිලිකන් ඩයොක්සයිඩ්",
        "ශීතකරණ හා එයරසෝල්වල භාවිත කළ CFC සීමා කිරීමට 1987 මොන්ට්‍රියල් සම්මුතිය (Montreal Protocol) අත්සන් කෙරිණි."),
      q(t, "ශීත රාත්‍රියක පොළොවට ආසන්න වායු ස්තරය ඉහළ වායු ස්තරයට වඩා සිසිල් වී දූෂිත වායු පොළොව අසල රැඳීමේ තත්ත්වය කුමක්ද?",
        "උෂ්ණත්ව ප්‍රතිලෝමනය (Temperature Inversion)", "සිරස් සංවහන ධාරා (Convection Currents)", "කඳු වැසි මුවාව (Rain Shadow)", "අන්තර් නිවර්තන අභිසාරිතාව (ITCZ)",
        "සාමාන්‍යයෙන් උස වැඩිවත්ම සිසිල් වුවද ප්‍රතිලෝමනයේදී උණුසුම් වාතය පියනක් මෙන් සිසිල් වාතය සිර කරයි."),
      q(t, "පොළොවට ආසන්න වාතයේ ජල වාෂ්ප ඝනීභවනය වීමෙන් තණකොළ හා පත්‍ර මත ඇතිවන ජල බිඳිති හඳුන්වන්නේ කුමන නමකින්ද?",
        "පින්න (Dew)", "හිම (Snow)", "හිම කැට (Hail)", "මීදුම (Fog)",
        "රාත්‍රියේදී තණකොළ හා පත්‍ර පිණි ලක්ෂ්‍යයට (Dew Point) වඩා සිසිල් වූ විට පින්න සෑදේ."),
      q(t, "උෂ්ණත්වය 0°C ට වඩා පහළ බැස ඇති විට ජල වාෂ්ප ද්‍රව නොවී කෙළින්ම සුදු අයිස් ස්ඵටික ලෙස පොළොවේ තැන්පත් වීම කුමක්ද?",
        "තුහින හෙවත් මල් තුහින (Frost)", "ඝන පොළොව ආසන්න මීදුම (Fog)", "ශාක පත්‍ර මත බැඳෙන පින්න (Dew)", "කැටි වැහි වළාකුළු වැසි (Sleet)",
        "ශ්‍රී ලංකාවේ නුවරඑළිය ප්‍රදේශයේ දෙසැම්බර්-ජනවාරි සීතල රාත්‍රීන්හි මල් තුහින පතිත වේ."),
      q(t, "ඉහළින් පවතින කඳු මුදුනකට වඩා සමුද්‍ර මට්ටම ආසන්න නිම්නයක් උණුසුම් වීමට ප්‍රධාන හේතුව කුමක්ද?",
        "පහළ උන්නතාංශයේදී වායු ඝනත්වය හා ජල වාෂ්ප වැඩි නිසා භෞමික විකිරණය වැඩිපුර අවශෝෂණය කිරීම", "සමුද්‍ර මට්ටමේ පිහිටි නිම්න කඳු මුදුන්වලට වඩා සූර්යයාට ආසන්න දුරකින් පිහිටා තිබීම", "කඳු මුදුන්වල වායු ඝනත්වය හා වායු පීඩනය නිම්නවලට වඩා අතිශයින් ඉහළ අගයක් ගැනීම", "සමුද්‍ර මට්ටම ආසන්නයේදී පෘථිවියේ ගුරුත්වාකර්ෂණ බලය සම්පූර්ණයෙන්ම නැති වී යාම",
        "වායුගෝලය ප්‍රධාන වශයෙන් රත් වන්නේ පෘථිවි පෘෂ්ඨයෙන් පිටවන අධෝරක්ත විකිරණය මගින් පහළ සිට ඉහළටය."),
      q(t, "ගොඩබිම හා ජලය රත්වීමේ වේගය අනුව ගත් කල ග්‍රීෂ්මයේදී ගොඩබිම හා ජලය හැසිරෙන්නේ කෙසේද?",
        "ගොඩබිම ජලයට වඩා ඉක්මනින් රත් වී ඉක්මනින් සිසිල් වේ", "ජලය ගොඩබිමට වඩා ඉක්මනින් රත් වී ඉක්මනින් සිසිල් වේ", "ගොඩබිම හා ජලය යන දෙකම සෑම විටම සමාන වේගයෙන් රත් වේ", "සූර්ය කිරණ පතිත වුවද ගොඩබිම කිසිදා උණුසුම් නොවී පවතී",
        "ජලයේ ඉහළ විශිෂ්ට තාප ධාරිතාව හා තාප විනිවිද යාම නිසා සාගර රත්වීමට හා සිසිල් වීමට වැඩි කලක් ගත වේ."),
      q(t, "සාගර ආශ්‍රිත දූපත් හා වෙරළබඩ නගරවල (උදා: කොළඹ) දෛනික හා වාර්ෂික උෂ්ණත්ව අන්තරය කුඩා වන්නේ ඇයි?",
        "සාගරයේ සමතුලිත කිරීමේ බලපෑම (Maritime Influence) නිසාය", "වෙරළබඩ ප්‍රදේශවල උස කඳු වැටි බහුලව පිහිටා ඇති නිසාය", "නාගරික වෙරළබඩ ප්‍රදේශවල වනාන්තර ආවරණය නොමැති නිසාය", "මුහුදු මට්ටමේදී වායුගෝලීය පීඩනය ශුන්‍ය අගයක් ගන්නා නිසාය",
        "මහාද්වීප අභ්‍යන්තර නගරවල (Continental Climate) ග්‍රීෂ්ම-ශීත උෂ්ණත්ව වෙනස ඉතා අධික වේ."),
      q(t, "අත්ලාන්තික් සාගරයේ උණුසුම් 'ගල්ෆ් දියවැල' (Gulf Stream) බටහිර යුරෝපයට ඇති කරන ධනාත්මක බලපෑම කුමක්ද?",
        "සමාන අක්ෂාංශයේ කැනඩාවට වඩා බටහිර යුරෝපීය වරායන් ශීත සෘතුවේදී අයිස්වලින් තොරව තැබීම", "බටහිර යුරෝපීය රටවල් පුරාම විශාල උණුසුම් වැලි කාන්තාර පද්ධති නිර්මාණය කිරීම", "උතුරු යුරෝපයට වසර පුරාම සමක වැසි වනාන්තර දේශගුණ තත්ත්වයන් ගෙන ඒම", "මුළු යුරෝපා මහාද්වීපයටම ලැබෙන වාර්ෂික වර්ෂාපතනය සම්පූර්ණයෙන්ම නවතා දැමීම",
        "නෝර්වේ හි උතුරු වරායන් පවා ශීත සෘතුවේදී නාවික ගමනාගමනයට විවෘතව පවතින්නේ මෙම උණුසුම් දියවැල නිසාය."),
      q(t, "සීතල 'ලැබ්‍රඩෝ දියවැල' සහ උණුසුම් 'ගල්ෆ් දියවැල' හමුවන නිව්ෆවුන්ඩ්ලන්ත මුහුදු ප්‍රදේශයේ ප්‍රධාන ලක්ෂණ දෙක කුමක්ද?",
        "ඝන මීදුම හට ගැනීම සහ ලෝකයේ පොහොසත්ම මත්ස්‍ය බිම් බිහි වීම", "කොරල් පර හට ගැනීම සහ මුහුදු ජලයේ උණුසුම අධික ලෙස ඉහළ යාම", "වෙරළබඩ ප්‍රදේශවල මුහුදු ජලය සිඳී ගොස් විශාල ලුණු ලේවායන් නිර්මාණය වීම", "සාගර පතුලේ සක්‍රිය ගිනිකඳු පිපිරී ගොස් අලුතින් ගිනිකඳු දූපත් බිහි වීම",
        "සීතල හා උණුසුම් දියවැල් මිශ්‍ර වීමෙන් ප්ලවාංග (Plankton) බහුල වී මසුන් ආකර්ෂණය වේ."),
      q(t, "ජපානයේ වෙරළ අසල හමුවන උණුසුම් 'කුරෝෂියෝ' සහ සීතල 'ඔයාෂියෝ' දියවැල් නිසා ඇතිවන ප්‍රධාන ආර්ථික වාසිය කුමක්ද?",
        "ලෝකයේ ප්‍රධානතම වාණිජ මත්ස්‍ය කලාපයක් නිර්මාණය වීම", "මුහුදු ජලයෙන් පානීය ජලය පෙරීමේ කර්මාන්තය පමණක් දියුණු වීම", "සාගර පතුලේ ඛනිජ තෙල් හා ස්වාභාවික වායු නිධි ඉක්මනින් සෑදීම", "රට පුරාම වසරේ සෑම දිනකම ලැබෙන සූර්යාලෝක පැය ගණන වැඩි වීම",
        "උතුරු පැසිෆික් හි මෙම මිශ්‍රණ කලාපය ජපාන ධීවර කර්මාන්තයේ පදනමයි."),
      q(t, "ශ්‍රී ලංකාවේ පළමු අන්තර් මෝසම් (First Inter-monsoon) වැසි කාලසීමාව වන්නේ කුමන මාසවලදීද?",
        "මාර්තු සිට අප්‍රේල් දක්වා කාලය තුළය", "ජූනි සිට අගෝස්තු දක්වා කාලය තුළය", "දෙසැම්බර් සිට පෙබරවාරි දක්වා කාලය තුළය", "ඔක්තෝබර් සිට නොවැම්බර් දක්වා කාලය තුළය",
        "සවස් කාලයේ හා රාත්‍රියේදී ගිගුරුම් සහිත සංවහන වැසි මාර්තු–අප්‍රේල් කාලයේ ලැබේ."),
      q(t, "ශ්‍රී ලංකාවේ දෙවන අන්තර් මෝසම් කාලයේදී (ඔක්තෝබර්–නොවැම්බර්) දිවයින පුරා පුළුල් වර්ෂාපතනයක් ඇති වන්නේ ඇයි?",
        "සංවහන වැසිවලට අමතරව බෙංගාල බොක්කේ හටගන්නා අවපාත හා සුළි කුණාටු බලපාන බැවිනි", "නිරිතදිග මෝසම් සුළං ප්‍රවාහයේ වේගය උපරිම මට්ටමට ළඟා වී හමන බැවිනි", "හිමාල කඳු වැටියේ හිම තට්ටු දියවී ගංගා ජල මට්ටම ඉහළ නැග ගලා එන බැවිනි", "මධ්‍යම කඳුකරයේ නැගෙනහිර බෑවුම් දිගේ වියළි කච්චාන් සුළං ප්‍රබලව හමන බැවිනි",
        "මෙම කාලය ශ්‍රී ලංකාවේ සමතුලිතවම වැසි ව්‍යාප්ත වන සෘතුවයි."),
      q(t, "යම් ප්‍රදේශයක සාමාන්‍ය වර්ෂාපතනයට වඩා දීර්ඝ කාලයක් වර්ෂාව අඩු වීමෙන් ඇතිවන 'කාලගුණ විද්‍යාත්මක නියඟය' යනු කුමක්ද?",
        "දීර්ඝ කාලයක් පුරා සාමාන්‍යයට වඩා සැලකිය යුතු ලෙස වර්ෂාපතනය අඩු වීම", "විශාල ජලාශයක ප්‍රධාන වේල්ල හදිසියේ බිඳී ගොස් ජලය බැස යාම", "මෝසම් වැසි හේතුවෙන් ප්‍රධාන ගංගාවක් දෙගොඩතලා පිටාර ගැලීම", "ධ්‍රැවීය ප්‍රදේශවල පිහිටි ග්ලැසියර සහ අයිස් කඳු වේගයෙන් දියවී යාම",
        "කාලගුණ විද්‍යාත්මක නියඟය පසුව කෘෂිකාර්මික හා ජල විද්‍යාත්මක නියඟ බවට පත්විය හැක."),
      q(t, "වාතයේ අඩංගු සැබෑ ජල වාෂ්ප ප්‍රමාණය, එම උෂ්ණත්වයේදී වාතයට දරාගත හැකි උපරිම ජල වාෂ්ප ප්‍රමාණයට දක්වන ප්‍රතිශතය කුමක්ද?",
        "සාපේක්ෂ ආර්ද්‍රතාව (Relative Humidity)", "නිරපේක්ෂ ආර්ද්‍රතාව (Absolute Humidity)", "වර්ෂාපතන තීව්‍රතාව (Rainfall Intensity)", "වාෂ්පීකරණ අනුපාතය (Evaporation Rate)",
        "වාතය සම්පූර්ණයෙන්ම ජල වාෂ්පවලින් සංතෘප්ත වූ විට සාපේක්ෂ ආර්ද්‍රතාව 100% ක් වේ."),
      q(t, "වායු ස්කන්ධයක උෂ්ණත්වය ඉහළ යන විට එහි ජල වාෂ්ප ප්‍රමාණය නොවෙනස්ව පවතී නම් සාපේක්ෂ ආර්ද්‍රතාවට කුමක් සිදුවේද?",
        "සාපේක්ෂ ආර්ද්‍රතාව ක්‍රමයෙන් අඩු වේ", "සාපේක්ෂ ආර්ද්‍රතාව ක්‍රමයෙන් වැඩි වේ", "සාපේක්ෂ ආර්ද්‍රතාව කිසිසේත් වෙනස් නොවේ", "සාපේක්ෂ ආර්ද්‍රතාව 100% දක්වා ඉහළ යයි",
        "උණුසුම් වාතයට වැඩි ජල වාෂ්ප ප්‍රමාණයක් දරාගත හැකි බැවින් සාපේක්ෂ ආර්ද්‍රතාව පහළ බසී."),
      q(t, "හිම කැට වර්ෂාව (Hail) ඇති වීමට විශේෂයෙන්ම දායක වන වායුගෝලීය ක්‍රියාවලිය කුමක්ද?",
        "කැටි වැහි වළාකුළු තුළ ඇති ප්‍රබල වායු ධාරා මගින් ජල බිඳිති අධිශීතල කලාපයට ගෙන යාම", "සමකයේ සුළං නොමැති සන්සුන් වායු කලාපය තුළ ජල වාෂ්ප එකතු වී තැන්පත් වීම", "උදෑසන කාලයේදී පොළොවට ආසන්න මීදුම ඝනීභවනය වී තණකොළ මත බැඳී යාම", "අභ්‍යවකාශයේ සිට වායුගෝලයට ඇතුළු වන උල්කාපාත කැබලි පොළොවට පතිත වීම",
        "අයිස් කැට වටා තට්ටු වශයෙන් අයිස් බැඳී බර වැඩි වූ පසු පොළොවට පතිත වේ."),
      q(t, "ගෝලීය උණුසුම් වීම හේතුවෙන් මුහුදු මට්ටම ඉහළ යාමට ප්‍රධාන වශයෙන් බලපාන සාධක දෙක මොනවාද?",
        "සාගර ජලයේ තාප ප්‍රසාරණය සහ ගොඩබිම ඇති ග්ලැසියර හා අයිස් තට්ටු දියවීම", "ආක්ටික් සාගරයේ පාවෙන මුහුදු අයිස් කුට්ටි දියවී සාගර ජලයට එකතු වීම පමණි", "මහාද්වීපවල ගංගාවල ගලා යන මිරිදිය ජල ප්‍රමාණය සැලකිය යුතු ලෙස අඩු වීම", "සාගර පතුලේ සිදුවන භූ කම්පන හා භූ තැටි චලන වේගය ඉහළ මට්ටමකට පැමිණීම",
        "සාගර ජලය රත් වන විට පරිමාව ප්‍රසාරණය වීමත් ග්‍රීන්ලන්ත-ඇන්ටාක්ටික් අයිස් දියවීමත් මුහුදු මට්ටම ඉහළ දමයි."),
      q(t, "වායුගෝලයේ ඇති අධික සල්ෆර් ඩයොක්සයිඩ් (SO2) සහ නයිට්‍රජන් ඔක්සයිඩ් (NOx) ජල වාෂ්ප සමඟ එක්වීමෙන් ඇතිවන ගැටලුව කුමක්ද?",
        "අම්ල වැසි (Acid Rain) ඇති වීම", "ඕසෝන් ස්තරය අලුතින් ගොඩනැගීම", "සක්‍රිය ගිනිකඳු පිපිරීම් ඇති වීම", "භූගත ජල මට්ටම ඉහළ යාම",
        "අම්ල වැසි වනාන්තරවලට, ජලජ ජීවීන්ට හා කිරිගරුඬ/හුණුගල් ගොඩනැගිලිවලට හානි කරයි."),
      q(t, "කාලගුණ සිතියමක 'L' හෝ 'Low' අකුරින් සලකුණු කර ඇති අඩු පීඩන මධ්‍යස්ථානයක සාමාන්‍ය කාලගුණය කෙබඳුද?",
        "වළාකුළු සහිත, වැසි හා සුළං සහිත අස්ථාවර කාලගුණයක් පවතී", "අහස සම්පූර්ණයෙන් පැහැදිලි ඉතා වියළි කාලගුණයක් පවතී", "සුළං හමා යාම සම්පූර්ණයෙන්ම නැති සන්සුන් තත්ත්වයක් පවතී", "දැඩි හිම තුහින සහිත පැහැදිලි ශීතල රාත්‍රී කාලගුණයක් පවතී",
        "අඩු පීඩන කලාපවලදී වාතය ඇතුළට ඇදී ඉහළ නැග ඝනීභවනය වී වළාකුළු හා වැසි සාදයි."),
      q(t, "කාලගුණ සිතියමක සම-පීඩන රේඛා (Isobars) ඉතා ළංව පිහිටි ස්ථානයක කාලගුණික ලක්ෂණය කුමක්ද?",
        "සුළඟේ වේගය ඉතා අධික වීම", "සුළඟ කිසිසේත්ම නොහැමීම", "වායු උෂ්ණත්වය ශුන්‍ය වීම", "දිවා කාලයේ අඳුරු වීම",
        "කෙටි දුරකින් පීඩන වෙනස විශාල වීම (Steep Pressure Gradient) ප්‍රබල සුළං ජනනය කරයි."),
      q(t, "සමකය දෙපස වායුගෝලීය තත්ත්වය හේතුවෙන් ඇමසන් වැසි වනාන්තරයේ වැසි වැඩිපුරම ලැබෙන වේලාව කුමක්ද?",
        "සවස 2:00 සිට 4:00 දක්වා කාලය තුළ", "හිමිදිරි උදෑසන 6:00 කාලය තුළ", "මධ්‍යම රාත්‍රී 12:00 කාලය තුළ", "පෙරවරු 9:00 සිට 10:00 දක්වා",
        "උදෑසන සිට රත්වන තෙත් වාතය දහවල් වන විට ඉහළ නැග සවස ගිගුරුම් වැසි ඇති කරයි."),
      q(t, "කඳු පාමුල නිම්නවල රාත්‍රී කාලයේ සිසිල් බර වාතය බෑවුම් දිගේ පහළට රූරා යාමෙන් ඇතිවන සුළඟ කුමක්ද?",
        "කැටබැටික් හෙවත් කඳු සුළඟ", "ඇනබැටික් හෙවත් නිම්න සුළඟ", "ඊසානදිග හා ගිනිකොන වෙළඳ සුළඟ", "සෘතුමය නිරිතදිග මෝසම් සුළඟ",
        "දිවා කාලයේදී රත් වූ වාතය නිම්නයේ සිට කඳු මුදුන් දෙසට ඉහළ නගින විට එය ඇනබැටික් (Valley Breeze) නම් වේ."),
      q(t, "ලෝකයේ වැඩිම වාර්ෂික වර්ෂාපතනයක් ලැබෙන මව්සින්රාම් (Mawsynram) සහ චෙරාපුංජි පිහිටා ඇත්තේ කුමන රටේද?",
        "ඉන්දියාවේ මේඝාලය ප්‍රාන්තයේය", "බ්‍රසීලයේ ඇමසන් ද්‍රෝණියේය", "ඉන්දුනීසියාවේ සුමාත්‍රා දූපතේය", "ශ්‍රී ලංකාවේ රත්නපුර දිස්ත්‍රික්කයේය",
        "බෙංගාල බොක්කේ සිට එන නිරිතදිග මෝසම් සුළං පුනීල ආකාර කඳු බෑවුම්වල ගැටීමෙන් මෙහි මි.මී. 11,000+ වැසි ලැබේ."),
      q(t, "දේශගුණ ප්‍රස්තාරයක (Climograph) සිරස් තීරු මගින් සහ වක්‍ර රේඛාව මගින් පිළිවෙළින් පෙන්වන්නේ මොනවාද?",
        "මාසික වර්ෂාපතනය සහ මාසික සාමාන්‍ය උෂ්ණත්වය", "සුළඟේ වේගය සහ වායුගෝලීය පීඩනය", "මුළු ජනගහනය සහ භූමි ප්‍රමාණය", "වගා බිම් ප්‍රමාණය සහ වනාන්තර වැස්ම",
        "Climograph එකක් දෙස බැලීමෙන් ප්‍රදේශය උතුරු හෝ දකුණු අර්ධගෝලයේද යන්න සහ දේශගුණ කලාපය හඳුනාගත හැක."),
      q(t, "දකුණු අර්ධගෝලයේ නගරයක (උදා: පර්ත් හෝ කේප්ටවුන්) දේශගුණ ප්‍රස්තාරයක උෂ්ණත්ව රේඛාවේ හැඩය කෙසේ දිස්වේද?",
        "ජූනි–ජූලි මාසවල පහළට නැමුණු 'U' හැඩයක් ගනී", "ජූනි–ජූලි මාසවල ඉහළට නැගුණු උච්චතම හැඩයක් ගනී", "වසරේ මාස දොළහ පුරාම සම්පූර්ණ සරල රේඛාවක් ගනී", "මාර්තු මාසයේදී පමණක් පහළ වැටෙන හැඩයක් ගනී",
        "දකුණු අර්ධගෝලයේ ජූනි-අගෝස්තු ශීත සෘතුව වන අතර දෙසැම්බර්-පෙබරවාරි ග්‍රීෂ්ම සෘතුවයි."),
      q(t, "ස්ටෙප් (Steppe) හෙවත් අර්ධ ශුෂ්ක දේශගුණ කලාපයේ ස්වභාවික වෘක්ෂලතා සැකැස්ම කෙබඳුද?",
        "කෙටි තෘණ බිම් හා විසිරුණු කටු පඳුරු පවතී", "උස සදාහරිත රූස්ස ගස් හා වැල් වර්ග පවතී", "අධික හිමට ඔරොත්තු දෙන කේතුධර වනාන්තර පවතී", "කරදිය වඩදියට හසුවන කඩොලාන වනාන්තර පවතී",
        "කාන්තාර හා තෙත් බිම් අතර සංක්‍රමණික කලාපයක් ලෙස ස්ටෙප් කලාප පවතී."),
      q(t, "මෝසම් කාලගුණික ලක්ෂණ සහිත දකුණු හා අග්නිදිග ආසියානු කලාපයේ ප්‍රධාන කෘෂිකාර්මික බෝගය කුමක්ද?",
        "වී ගොවිතැන (Paddy Cultivation)", "ඔලිව් සහ මිදි වගාව", "රයි සහ ඕට්ස් වගාව", "ටියුලිප් මල් වගාව",
        "ග්‍රීෂ්ම මෝසම් වැසි සහ උණුසුම් උෂ්ණත්වය වී වගාවට ඉතා යෝග්‍ය වේ."),
      q(t, "අධික සුළං සහිත වෙරළබඩ ස්ථානයක ගස් එකම දිශාවකට ඇල වී වැඩීම භූගෝල විද්‍යාවේදී පෙන්වා දෙන්නේ කුමක්ද?",
        "එම ප්‍රදේශයේ පවතින ප්‍රමුඛ සුළං දිශාවයි", "එම ප්‍රදේශයේ භූගත ජල මට්ටමයි", "එම ප්‍රදේශයේ පසේ ආම්ලිකතාවයි", "එම ප්‍රදේශයේ චුම්භක ක්ෂේත්‍රයයි",
        "වෙරළබඩ ප්‍රදේශවල පොල් හා කස ගස් ප්‍රමුඛ මුහුදු සුළං දිශාවට ඇල වී තිබෙනු දැකිය හැක."),
      q(t, "දේශගුණික විපර්යාස අවම කිරීමේ 'අවම කිරීමේ උපායමාර්ගයක්' (Mitigation) වන්නේ පහත කුමක්ද?",
        "සූර්ය හා සුළං වැනි පුනර්ජනනීය බලශක්ති භාවිතය හා නැවත වන වගාව", "මුහුදු රළ ගැලීම වැළැක්වීමට වෙරළ ආරක්ෂක කළුගල් බැමි බැඳීම", "ගංවතුර අවදානම් කලාපවල උස් කණු මත නිවාස හා ගොඩනැගිලි තැනීම", "නියඟයට ඔරොත්තු දෙන නව බෝග ප්‍රභේද හඳුන්වා දී වගා කිරීම",
        "විමෝචන අඩු කිරීම Mitigation වන අතර බලපෑම්වලට හැඩගැසීම Adaptation නම් වේ."),
      q(t, "දේශගුණික විපර්යාස සඳහා 'අනුවර්තනය වීමේ' (Adaptation) පියවරකට නිවැරදි උදාහරණයක් කුමක්ද?",
        "ලවණතාවට හා නියඟයට ඔරොත්තු දෙන වී ප්‍රභේද හඳුන්වා දී ගංවතුර පූර්ව අනතුරු ඇඟවීම් ශක්තිමත් කිරීම", "වැඩි වන විදුලි ඉල්ලුම සපුරාලීම සඳහා නව ගල් අඟුරු තාප බලාගාර ඉදිකිරීම", "නාගරික සංවර්ධන කටයුතු සඳහා ස්වාභාවික තෙත් කලාපීය වනාන්තර සම්පූර්ණයෙන් එළි කිරීම", "කර්මාන්තශාලා අපද්‍රව්‍ය හා ප්ලාස්ටික් එළිමහනේ පුළුස්සා දැමීම වේගවත් කිරීම",
        "දැනටමත් සිදුවන කාලගුණික වෙනස්කම්වල හානිය අවම කර ගනිමින් ජීවත් වීමට හැඩගැසීම Adaptation වේ."),
      q(t, "වායුගෝලයේ ජල වාෂ්ප හා වළාකුළු පෘථිවියේ තාප තුලනයට (Heat Budget) උපකාරී වන්නේ කෙසේද?",
        "දිවා කාලයේ සූර්ය කිරණ කොටසක් පරාවර්තනය කර රාත්‍රියේදී භෞමික තාපය රඳවා ගැනීමෙනි", "පෘථිවියට ලැබෙන සියලුම සූර්ය තාපය එවේලේම ආපසු අභ්‍යවකාශයට පරාවර්තනය කර යැවීමෙනි", "පෘථිවියේ ගිනිකඳු ක්‍රියාකාරිත්වය වැඩි කරමින් පෘථිවි අභ්‍යන්තර හරය උණුසුම් කිරීමෙනි", "පෘථිවි පෘෂ්ඨය වටා ඇති වායුගෝලීය ස්තර සියල්ල අභ්‍යවකාශයට ඉවත් කර දැමීමෙනි",
        "මේ නිසා වළාකුළු නොමැති කාන්තාරවල දහවල් අධික උණුසුමත් රාත්‍රී අධික සීතලත් පවතී."),
      q(t, "කාන්තාර ප්‍රදේශවල රාත්‍රී කාලය ඉතා සිසිල් වීමට ප්‍රධානතම හේතුව කුමක්ද?",
        "වළාකුළු හා ජල වාෂ්ප අඩු බැවින් තාපය ඉක්මනින් අභ්‍යවකාශයට විකිරණය වී යාම", "සෑම රාත්‍රියකම අධික ලෙස හිම පතනය හා තුහින සිදුවීම නිසා", "කාන්තාර පුරා ඝන සදාහරිත ගස් වැල් බහුලව පැතිර පවතින නිසා", "සියලුම උණුසුම් කාන්තාර ගැඹුරු සාගර වෙරළට ඉතා ළඟින් පිහිටි නිසා",
        "පැහැදිලි අහස සහ වියළි වාතය නිසා කාන්තාරවල දෛනික උෂ්ණත්ව පරාසය 30°C ඉක්මවිය හැක."),
      q(t, "භූගෝල විද්‍යාවේදී 'වාතාග්‍රයක් හෙවත් පෙරමුණක්' (Weather Front) ලෙස හඳුන්වන්නේ කුමක්ද?",
        "වෙනස් උෂ්ණත්ව හා ආර්ද්‍රතා ලක්ෂණ ඇති වායු ස්කන්ධ දෙකක් හමුවන සංක්‍රමණ කලාපය", "සමක රේඛාව දිගේ වසර පුරා නොවෙනස්ව පවතින නිශ්චල සුළං තීරුව", "සක්‍රිය ගිනිකන්දක මුදුනේ පිහිටි ලාවා පිටවන ආවාටයේ බාහිර සීමාව", "මුහුදු වෙරළ දිගේ තරංග ක්‍රියාකාරිත්වයෙන් තැන්පත් වන දිගු වැලි තීරුව",
        "සීතල පෙරමුණු (Cold Front) සහ උණුසුම් පෙරමුණු (Warm Front) මධ්‍ය අක්ෂාංශ කාලගුණය පාලනය කරයි."),
      q(t, "කාලගුණ විද්‍යාවේදී 'වාෂ්පීභවනය' (Evapotranspiration) යන යෙදුමෙන් අදහස් කරන්නේ කුමක්ද?",
        "භූමියෙන් හා ජලාශවලින් සිදුවන වාෂ්පීකරණයත් ශාක පත්‍ර මගින් සිදුවන උත්ස්වේදනයත් යන දෙකෙහිම එකතුවයි", "වළාකුළුවල ඇති ජල බිඳිති ගුරුත්වාකර්ෂණය යටතේ වර්ෂාව ලෙස පොළොවට වැටීම පමණි", "ධ්‍රැවීය කලාපවල උෂ්ණත්වය පහළ බැසීම නිසා ජලය ඝන අයිස් බවට පත්වීමයි", "ඇනිමෝමීටර උපකරණය ආධාරයෙන් පොළොව මතුපිට හමන සුළඟේ වේගය මැන බැලීමයි",
        "ලයිසිමීටර (Lysimeter) මගින් වාෂ්පීභවනය හා ජල සමතුලිතතාව මනිනු ලැබේ."),
      q(t, "මෝසම් දේශගුණය සහ සමක දේශගුණය අතර පවතින ප්‍රධානතම සමානකම කුමක්ද?",
        "වසර පුරා ඉහළ මාසික උෂ්ණත්වයක් (සෑම මාසයකම 18°C ට වැඩි) පැවතීම", "වසර පුරාම සෑම මාසයකම අධික හිම පතනයක් සිදුවීම", "මාස හයක් පුරා පවතින දිගු ශීත සෘතුවක් දැකිය හැකි වීම", "වසර පුරාම ග්‍රහලෝක සුළං සම්පූර්ණයෙන්ම නැතිව පැවතීම",
        "දෙකම Köppen 'A' (නිවර්තන) දේශගුණ කාණ්ඩයට අයත් වන නමුත් වර්ෂාපතන රටාවෙන් වෙනස් වේ."),
      q(t, "වයඹදිග යුරෝපයේ (උදා: බ්‍රිතාන්‍යය, නෙදර්ලන්තය) පවතින දේශගුණ කලාපය හඳුන්වන්නේ කුමන නමකින්ද?",
        "සෞම්‍ය සමුද්‍රික දේශගුණය (Temperate Maritime)", "මධ්‍යධරණී දේශගුණය (Mediterranean Climate)", "ටයිගා කේතුධර දේශගුණය (Taiga Climate)", "නිවර්තන මෝසම් දේශගුණය (Tropical Monsoon)",
        "බටහිර සුළං හා උණුසුම් උතුරු අත්ලාන්තික් දියවැල නිසා වසර පුරා මෘදු සිසිල් වැසි ලැබේ."),
      q(t, "2015 දී එළැඹුණු පැරිස් දේශගුණික ගිවිසුමේ (Paris Agreement) ප්‍රධාන ගෝලීය අරමුණ කුමක්ද?",
        "ගෝලීය සාමාන්‍ය උෂ්ණත්ව ඉහළ යාම පූර්ව-කාර්මික මට්ටමට වඩා 1.5°C–2°C අතර සීමා කිරීම", "ලෝකයේ සියලුම ප්‍රධාන ගංගාවල ජලය විදුලිය නිපදවීමට සම්පූර්ණයෙන් හරස් කර වසා දැමීම", "හරිතාගාර වායු අවම කිරීමට මිනිසුන්ගේ සියලුම අභ්‍යවකාශ ගමන් හා චන්ද්‍රිකා තහනම් කිරීම", "බලශක්ති අර්බුදය විසඳීමට ලොව පුරා ගල් අඟුරු බලාගාර භාවිතය දෙගුණයකින් ඉහළ දැමීම",
        "දේශගුණික විපර්යාස අවම කිරීම සඳහා රටවල් 190 කට වැඩි සංඛ්‍යාවක් මෙයට එක්ව ඇත."),
      q(t, "ගොඩබිම් මතුපිට ඇති හිම වැස්ම අඩු වන විට පෘථිවිය තවදුරටත් වේගයෙන් රත් වීමේ ක්‍රියාවලිය කුමක් ලෙස හැඳින්වේද?",
        "ධනාත්මක ප්‍රතිපෝෂණ ක්‍රියාවලියකි (Positive Feedback)", "සෘණාත්මක ප්‍රතිපෝෂණ ක්‍රියාවලියකි (Negative Feedback)", "වායුගෝලීය උෂ්ණත්ව ප්‍රතිලෝමනයකි (Temperature Inversion)", "දිගු කාලීන ශීත යුග ඇතිවීමකි (Glaciation)",
        "හිම දියවීමෙන් ඇල්බෙඩෝව අඩු වී තාප අවශෝෂණය වැඩි වීමෙන් තවත් හිම දිය වීම වේගවත් වේ."),
      q(t, "උස කඳු වැටියක (උදා: කිලිමන්ජාරෝ හෝ ඇන්ඩීස්) පාමුල සිට මුදුන දක්වා යාමේදී වෘක්ෂලතා හා දේශගුණය වෙනස් වන්නේ කෙසේද?",
        "නිවර්තන වනාන්තරවල සිට ඇල්පයින් තණබිම් හා හිම වැස්ම දක්වා ක්‍රමයෙන් වෙනස් වේ", "පාමුල ප්‍රදේශයේ හිම තට්ටු පවතින අතර කඳු මුදුනේ උණුසුම් වැලි කාන්තාර පවතී", "උන්නතාංශය කොපමණ ඉහළ ගියද කඳු පාමුල සිට මුදුන දක්වා කිසිදු වෙනසක් සිදු නොවේ", "කඳු මුදුනේ උසම ස්ථානවල කරදිය වඩදියට හසුවන කඩොලාන වනාන්තර පැතිර පවතී",
        "සමකය ආසන්නයේ ඇති කිලිමන්ජාරෝ කඳු මුදුනේ පවා ග්ලැසියර පවතින්නේ උන්නතාංශය නිසාය."),
      q(t, "කාලගුණ සිතියමක 'අහස වළාකුළු වලින් වැසී ඇති ප්‍රමාණය' (Cloud Cover) නිරූපණය කරන්නේ කුමන ඒකකයකින්ද?",
        "ඔක්ටා (Oktas - අටෙන් පංගු 0 සිට 8 දක්වා)", "මිලිමීටර් (Millimetres - ඝන වර්ෂාපතන ඒකක)", "හෙක්ටොපැස්කල් (Hectopascals - වායු පීඩන ඒකක)", "නොට්ස් (Knots - සුළං වේග මැනීමේ ඒකක)",
        "සම්පූර්ණයෙන් වළාකුළු වලින් වැසුණු අහස 8/8 (8 oktas) ලෙස කාලගුණ සිතියම්වල දක්වයි."),
      q(t, "අධික ආර්ද්‍රතාව හා උෂ්ණත්වය ඇති සමක ප්‍රදේශවල පස ඉක්මනින් නිසරු වීමට (Leaching) බලපාන කාලගුණික සාධකය කුමක්ද?",
        "අධික වර්ෂාපතනය නිසා පසේ දියවන ඛනිජ හා පෝෂක පහළ ස්තරවලට සේදී යාම", "වසර පුරා හමන ග්‍රහලෝක සුළං වේගයේ අඩුකම නිසා පස වාතනය නොවීම", "රාත්‍රී කාලයේදී පස මතුපිට උෂ්ණත්වය පහළ බැස හිම මිදීම සිදුවීම", "අහසේ වළාකුළු ආවරණය අඩුවී සෘජු හිරු එළිය නොමැති වීම",
        "එබැවින් නිවර්තන වැසි වනාන්තරවල පෝෂක වැඩි කොටසක් ගබඩා වී ඇත්තේ පසේ නොව ජීවමාන ගස්වලය."),
      q(t, "බෝෆර්ට් පරිමාණය (Beaufort Scale) භාවිත කරනු ලබන්නේ කුමන කාලගුණික මූලද්‍රව්‍යය නිරීක්ෂණය කිරීම සඳහාද?",
        "සුළඟේ වේගය හා සාගර හා ගොඩබිම් මත එහි නිරීක්ෂිත බලපෑම්", "භූ කබොලේ සිදුවන භූමිකම්පාවල විශාලත්වය හා තීව්‍රතාව", "මෝසම් කාලයේදී ලැබෙන වාර්ෂික වර්ෂාපතන මට්ටම", "වායුගෝලයේ අඩංගු ජල වාෂ්ප හෙවත් සාපේක්ෂ ආර්ද්‍රතාව",
        "0 (සන්සුන්) සිට 12 (සුළි සුළං/Hurricane) දක්වා බෝෆර්ට් පරිමාණයෙන් සුළඟ වර්ග කෙරේ."),
      q(t, "ඉහළ අහසේ පරිවර්තී ගෝලය හා අපවර්තී ගෝලය අතර මායිමේ වේගයෙන් හමන පටු සුළං ප්‍රවාහ මොනවාද?",
        "ඉහළ වායුගෝලයේ හමන ජෙට් ප්‍රවාහ (Jet Streams)", "නිවර්තන කලාපීය වෙළඳ සුළං (Trade Winds)", "වෙරළබඩ දෛනික මුහුදු සුළං (Sea Breezes)", "රාත්‍රී කාලයේ හමන ගොඩබිම් සුළං (Land Breezes)",
        "Subtropical හා Polar Front Jet Streams ගෝලීය කාලගුණ පද්ධති හා ගුවන් ගමන් වේගයට බලපායි."),
      q(t, "උණුසුම් මධ්‍යධරණී කලාපයේ වැඩෙන ශාක ග්‍රීෂ්ම නියඟයට ඔරොත්තු දීමට දක්වන අනුවර්තනයක් කුමක්ද?",
        "කුඩා ඉටිමය පත්‍ර, ගැඹුරු මුල් සහ ඝන පොතු පැවතීම", "ජලය ඉක්මනින් පිට කිරීමට පළල් සිහින් පත්‍ර පැවතීම", "වගුරු බිම්වලට උචිත පොළොව මතුපිට නොගැඹුරු මුල් පැවතීම", "ලවණ වගුරුවල හුස්ම ගැනීමට වායු මුල් පැවතීම",
        "ඔලිව්, මිදි හා කෝක් ඕක් වැනි ශාක (Sclerophyllous vegetation) ජල වාෂ්පීකරණය අවම කර ගනී."),
      q(t, "පෘථිවි පෘෂ්ඨය මත ඇතිවන මීදුම (Fog) හා ඉහළ අහසේ ඇතිවන වළාකුළු අතර ඇති ප්‍රධාන වෙනස කුමක්ද?",
        "මීදුම පොළොව මතුපිට හෝ ආසන්නයේ සෑදෙන පහළ ස්තර වළාකුළක් වීමයි", "මීදුම ජල වාෂ්පවලින් නොව සම්පූර්ණයෙන්ම දූවිලි අංශුවලින් පමණක් සෑදීමයි", "ඉහළ අහසේ වළාකුළු තුළ කිසිදු ජල බිඳිති හෝ අයිස් ස්ඵටික නොමැති වීමයි", "මීදුම දිවා කාලයේ පමණක් සෑදෙන අතර රාත්‍රී කාලයේ කිසිදා නොසෑදීමයි",
        "තෙත් වාතය පොළොව අසලදී පිණි ලක්ෂ්‍යයට සිසිල් වූ විට Radiation Fog හෝ Advection Fog හටගනී."),
      q(t, "වායුගෝලයේ ජල වාෂ්ප ඝනීභවනය වී වළාකුළු බිඳිති සෑදීම ආරම්භ වීමට උපකාරී වන කුඩා අංශු මොනවාද?",
        "මුහුදු ලුණු හා දූවිලි වැනි ජලාකර්ෂක ඝනීභවන න්‍යෂ්ටි", "අපවර්තී ගෝලයේ පිහිටි ඕසෝන් වායු අණු", "වියළි වාතයේ බහුලව පවතින නයිට්‍රජන් වායු අණු", "වායුගෝලයේ අඩංගු නිෂ්ක්‍රීය ආගන් පරමාණු",
        "මුහුදු ලුණු, දූවිලි හා දුම් අංශු නොමැතිව ස්වභාවිකව වළාකුළු නිර්මාණය වීම ඉතා අපහසුය."),
      q(t, "කෘත්‍රිම වැසි ඇති කිරීමේදී (Cloud Seeding) වළාකුළු තුළට ඉසිනු ලබන ප්‍රධාන රසායනික ද්‍රව්‍යයක් කුමක්ද?",
        "සිල්වර් අයඩයිඩ් (Silver Iodide) හෝ වියළි අයිස්", "සෝඩියම් හයිඩ්‍රොක්සයිඩ් (Sodium Hydroxide)", "සාන්ද්‍ර සල්ෆියුරික් අම්ලය (Sulphuric Acid)", "ද්‍රව මීතේන් වායුව (Liquid Methane)",
        "Silver Iodide ස්ඵටික අයිස් න්‍යෂ්ටි ලෙස ක්‍රියා කර වළාකුළු බිඳිති විශාල වීමට උපකාර කරයි."),
      q(t, "වායු පීඩනය මැනීම සඳහා රසදිය රහිතව භාවිත කරන පහසුවෙන් රැගෙන යා හැකි උපකරණය කුමක්ද?",
        "නිර්ද්‍රව බැරෝමීටරය (Aneroid Barometer)", "සම්මත වර්ෂා මානය (Standard Rain Gauge)", "විදුලි ඇනිමෝමීටරය (Cup Anemometer)", "තෙත් බල්බ හයිග්‍රොමීටරය (Wet-bulb Hygrometer)",
        "මෙහි රික්ත කළ ලෝහ පෙට්ටියක් පීඩන වෙනස්වීම් අනුව හැකිලීම හා ප්‍රසාරණය වීම සිදුවේ."),
      q(t, "කාලගුණ බැරෝමීටරයේ පාඨාංකය හදිසියේම ඉතා වේගයෙන් පහළ වැටීමෙන් පෙන්නුම් කරන්නේ කුමක්ද?",
        "ළඟ එන තද සුළං සහිත කුණාටුවක් හෝ ගැඹුරු අවපාතයකි", "සති ගණනක් පුරා පවතින පැහැදිලි වියළි අහසකි", "දීර්ඝ කාලයක් පවතින දැඩි කාලගුණික නියඟයකි", "ධ්‍රැවීය කලාපයේ හිම මිදීම සම්පූර්ණයෙන් නතර වීමකි",
        "වේගවත් පීඩන බැස්ම අස්ථාවර කාලගුණික පෙරමුණක් හෝ සුළි සුළඟක පෙර නිමිත්තකි."),
      q(t, "පරිවර්තී ගෝලයේ උස සමකයට ඉහළින් කි.මී. 16–18 ක් වුවද ධ්‍රැවවලදී කි.මී. 8 ක් පමණක් වන්නේ ඇයි?",
        "සමකයේදී අධික තාපය නිසා වාතය ප්‍රසාරණය වී ඉහළට සංවහනය වන බැවිනි", "ධ්‍රැවීය කලාපවල පෘථිවි ගුරුත්වාකර්ෂණ බලය සම්පූර්ණයෙන්ම නැති නිසාය", "සමකයට ඉහළ අහසේ ඕසෝන් වායු සාන්ද්‍රණය අධික මට්ටමක පවතින නිසාය", "සමක ප්‍රදේශයේ සාගර ජල ගැඹුර ධ්‍රැවීය සාගරවලට වඩා වැඩි නිසාය",
        "සීතල ධ්‍රැවීය වාතය ඝනත්වයෙන් වැඩි නිසා පොළොවට ආසන්නව හැකිලී පවතී."),
      q(t, "'ලා නිනා' (La Niña) තත්ත්වය යනු පැසිෆික් සාගරයේ ඇතිවන කුමන ආකාරයේ ස්වභාවයද?",
        "නැගෙනහිර හා මධ්‍යම පැසිෆික් සාගරයේ ජල උෂ්ණත්වය සාමාන්‍යයට වඩා සිසිල් වීම", "සමස්ත පැසිෆික් සාගරයම අසාමාන්‍ය ලෙස උණුසුම් වී වාෂ්පීකරණය ඉහළ යාම", "උතුරු හා දකුණු අත්ලාන්තික් සාගරයේ ජල මට්ටම සම්පූර්ණයෙන් වියළී යාම", "ඉන්දියානු සාගරයේ මෝසම් සුළං සම්පූර්ණයෙන්ම හමා යාම නතර වීම",
        "La Niña කාලවලදී දකුණු ආසියාවේ හා ඕස්ට්‍රේලියාවේ මෝසම් වැසි හා ගංවතුර තත්ත්වයන් උග්‍ර විය හැක."),
      q(t, "වසර පුරා මධ්‍යස්ථ උෂ්ණත්වය හා ප්‍රමාණවත් වැසි ඇති සෞම්‍ය කලාපයක ප්‍රධාන ආර්ථික වාසිය කුමක්ද?",
        "විවිධ ධාන්‍ය වගාව හා කිරි ගොවිතැන සඳහා හිතකර කෘෂිකාර්මික පරිසරයක් පැවතීම", "අධික හිම පතනය නිසා කිසිදු බෝගයක් වගා කළ නොහැකි වීම", "භූගත හා මතුපිට ජල සම්පත සම්පූර්ණයෙන්ම හිඟ වී පැවතීම", "වසරේ මාස දොළහ පුරාම භූමිය ස්ථිර අයිස් හා හිමවලින් වැසී පැවතීම",
        "සෞම්‍ය කලාපීය දේශගුණය (Temperate Zone) ලෝකයේ ප්‍රධාන ධාන්‍යාගාර පිහිටි කලාපයයි."),
      q(t, "නිරක්ෂීය වැසි වනාන්තර කලාපයේ ශාකවල දක්නට ලැබෙන ප්‍රධාන ව්‍යුහමය ලක්ෂණය කුමක්ද?",
        "හිරු එළිය සඳහා ඇති තරගය නිසා වියන් ස්තර කිහිපයක් ලෙස වැඩීම", "ජලය ආරක්ෂා කර ගැනීම සඳහා පත්‍ර කුඩා කටු බවට පත්වී තිබීම", "සුළඟට ඔරොත්තු දීමට තනි මීටර් එකක් පමණ උස පඳුරු ලෙස වැඩීම", "ශීත හා ග්‍රීෂ්ම සෘතු වෙනස නිසා වසරකට වරක් සියලු පත්‍ර හැලී යාම",
        "ඉහළම මතුවන ස්තරය (Emergent), වියන (Canopy) හා යටි රෝපණය ලෙස ස්තර 4–5 ක් පවතී."),
      q(t, "උප-ධ්‍රැවීය කේතුධර වනාන්තරවල (Taiga) ගස් කේතු ආකාර හැඩයක් ගැනීමට හේතුව කුමක්ද?",
        "අධික හිම පතනයේදී අතු මත හිම රැඳී කඩා වැටීම වැළැක්වීම සඳහා හිම ලිස්සා යාමටය", "වියළි කාලවලදී වැසි ජලය කඳ දෙසට එක්රැස් කර ගබඩා කර තබා ගැනීමටය", "හමන ධ්‍රැවීය සුළං වේගය වැඩි කර පරාගණය වේගවත් කර ගැනීමටය", "වනාන්තරයේ වෙසෙන විවිධ සතුන් ආහාර සඳහා ගසට ආකර්ෂණය කර ගැනීමටය",
        "පයින් හා ස්පෘස් ගස්වල ඉදිකටු පත්‍ර ජල හානිය හා හිම බර අවම කරයි."),
      q(t, "ශ්‍රී ලංකාවේ තෙත් කලාපයේ සාමාන්‍ය වාර්ෂික වර්ෂාපතන සීමාව කොපමණද?",
        "මිලිමීටර් 2,500 ට වැඩි ප්‍රමාණයකි", "මිලිමීටර් 500 ට අඩු ප්‍රමාණයකි", "මිලිමීටර් 900 සිට 1,100 අතර ප්‍රමාණයකි", "මිලිමීටර් 200 පමණ කුඩා ප්‍රමාණයකි",
        "ශ්‍රී ලංකාව මි.මී. 2,500 ට වැඩි තෙත් කලාපය, 1,750–2,500 අතරමැදි කලාපය හා 1,750 ට අඩු වියළි කලාපය ලෙස බෙදේ."),
      q(t, "ශ්‍රී ලංකාවේ වියළි කලාපයට වාර්ෂිකව ලැබෙන වර්ෂාපතනයෙන් වැඩිම කොටසක් ලැබෙන්නේ කුමන කාලසීමාවේදීද?",
        "ඔක්තෝබර් සිට පෙබරවාරි දක්වා දෙවන අන්තර් මෝසම හා ඊසානදිග මෝසම මගිනි", "මැයි සිට ජූලි දක්වා නිරිතදිග මෝසම් සුළං ප්‍රවාහය මගිනි", "ජූනි සිට අගෝස්තු දක්වා වියළි කච්චාන් සුළං ප්‍රවාහය මගිනි", "මාර්තු සිට මැයි දක්වා පළමු අන්තර් මෝසම් සුළං මගිනි",
        "මහ කන්නයේ වගා කටයුතු සඳහා වියළි කලාපයේ වැව් පිරෙන්නේ මෙම වැසි සමයෙනි."),
      q(t, "උෂ්ණත්වය මැනීමේදී 'උපරිම හා අවම උෂ්ණත්වමානය' (Six's Thermometer) සම්මත ලෙස කියවනු ලබන්නේ කුමක් සඳහාද?",
        "පැය 24 තුළ වාර්තා වූ වැඩිම හා අඩුම උෂ්ණත්වය සොයා දෛනික මධ්‍යන්‍යය ගණනය කිරීමටය", "පැය 24 පුරා හමන සුළඟේ වේගය හා දිශාව මැන සටහන් කර ගැනීමටය", "වර්ෂා මානය තුළ රැස්වූ මුළු වර්ෂාපතනය මිලිමීටර්වලින් ගණනය කිරීමටය", "වියළි හා තෙත් බල්බ ආධාරයෙන් වාතයේ සාපේක්ෂ ආර්ද්‍රතාව මැන ගැනීමටය",
        "(උපරිම + අවම) ÷ 2 මගින් දෛනික මධ්‍යන්‍ය උෂ්ණත්වය ලබා ගනී."),
      q(t, "සාමාන්‍යයෙන් දිනයේ වැඩිම උෂ්ණත්වය දහවල් 12:00 ට නොව සවස 2:00–3:00 අතර වාර්තා වන්නේ ඇයි?",
        "සූර්ය විකිරණයෙන් පොළොව රත් වී භෞමික තාපය වායුගෝලයට මුදා හැරීමට කාලයක් ගතවන බැවිනි", "සවස කාලයේදී පෘථිවිය සූර්යයාට ආසන්න දුරකින් කක්ෂයේ ගමන් කරන බැවිනි", "සවස කාලයේදී ඉහළ අහසේ වළාකුළු පොළොව මට්ටමට පහළ බසින බැවිනි", "දහවල් 12:00 වන විට පෘථිවි පෘෂ්ඨයට කිසිදු සූර්යාලෝකයක් නොලැබෙන බැවිනි",
        "ලැබෙන තාපය පිටවන තාපයට වඩා වැඩි වන තෙක් සවස 2–3 දක්වා උෂ්ණත්වය ඉහළ යයි."),
      q(t, "සූර්යගත ශක්තිය (Insolation) පෘථිවියට පැමිණීමේදී ඉන් වැඩි කොටසක් අවශෝෂණය වීමෙන් මුලින් රත් වන්නේ කුමක්ද?",
        "පෘථිවි ගොඩබිම් හා සාගර මතුපිට පෘෂ්ඨයයි", "අපවර්තී ගෝලයේ පිහිටි ඕසෝන් ස්තරය පමණි", "වායුගෝලයේ ඉහළම පිහිටි බහිර් ගෝලයයි", "මධ්‍ය ගෝලය හරහා වැටෙන උල්කාපාත අංශුයි",
        "වායුගෝලය සෘජු කෙටි තරංග සූර්ය කිරණවලට වඩා පොළොවෙන් පිටවන දිගු තරංග තාපයෙන් රත් වේ."),
      q(t, "කාලගුණ අනාවැකි සඳහා 'රේඩියෝසොන්ඩ්' (Radiosonde) බැලූන් මගින් සිදු කරන ප්‍රධාන කාර්යය කුමක්ද?",
        "ඉහළ වායුගෝලයේ උෂ්ණත්වය, පීඩනය හා ආර්ද්‍රතාව මැන රේඩියෝ සංඥා මගින් එවීම", "ගැඹුරු සාගර පතුලේ උෂ්ණත්වය හා මුහුදු පතුලේ ගැඹුර මැන සටහන් කිරීම", "පෘථිවි කබොලේ හටගන්නා භූ කම්පන තරංගවල තීව්‍රතාව සටහන් කර තැබීම", "කෘෂිකාර්මික බිම්වල පසේ ආම්ලිකතාව හෙවත් pH අගය මැන පරීක්ෂා කිරීම",
        "ලොව පුරා කාලගුණ මධ්‍යස්ථාන දිනපතා හයිඩ්‍රජන්/හීලියම් බැලූන් මගින් ඉහළ වායුගෝල දත්ත රැස් කරයි."),
      q(t, "කාබන් විමෝචනය අවම කිරීමේදී 'කාබන් සිංක්' (Carbon Sink) ලෙස හඳුන්වන ප්‍රධාන ස්වාභාවික පද්ධති මොනවාද?",
        "වනාන්තර, සාගර සහ පීට් වගුරු බිම්", "සක්‍රිය ගිනිකඳු සහ වියළි වැලි කාන්තාර", "නාගරික ප්‍රදේශ සහ කර්මාන්තශාලා කලාප", "උත්තර හා දක්ෂිණ ධ්‍රැවීය හිම කඳු පමණි",
        "ශාක හා සාගර ජලය වායුගෝලයේ ඇති CO2 සැලකිය යුතු ප්‍රමාණයක් අවශෝෂණය කර ගබඩා කරයි."),
      q(t, "මුහුදු මට්ටමින් ඉහළ කඳුකර ප්‍රදේශවල වායු පීඩනය සමුද්‍ර මට්ටමට වඩා අඩු වන්නේ ඇයි?",
        "ඉහළ යත්ම ඊට ඉහළින් ඇති වායු කුළුණේ බර හා ඝනත්වය අඩු වන බැවිනි", "කඳුකර ප්‍රදේශවල වායු උෂ්ණත්වය සමුද්‍ර මට්ටමට වඩා ඉතා ඉහළ බැවිනි", "උස කඳු මුදුන්වලදී පෘථිවි ගුරුත්වාකර්ෂණය ඉතා අධික වන බැවිනි", "කඳුකර ප්‍රදේශවලට ලැබෙන වාර්ෂික වර්ෂාපතනය අධික මට්ටමක පවතින බැවිනි",
        "මුහුදු මට්ටමේ සාමාන්‍ය පීඩනය 1013.25 mb වන අතර කි.මී. 5.5 ක උසකදී එය ඉන් අඩකට බසී."),
      q(t, "සමුද්‍ර මට්ටමේ සිට ඉහළට නගින වායු ස්කන්ධයක් අභ්‍යන්තර තාප හුවමාරුවකින් තොරව සිසිල් වීම සිදු වන්නේ කෙසේද?",
        "අඩු පීඩනය නිසා වාතය ප්‍රසාරණය වී ශක්තිය වැය වීමෙනි", "ඉහළ අහසේ ඇති අයිස් කුට්ටි සමඟ සෘජුව ගැටීමෙනි", "නොනවතින සංවහන වර්ෂාව පොළොවට පතිත වීමෙනි", "සූර්යයාගේ මතුපිට උෂ්ණත්වය ක්ෂණිකව සිසිල් වීමෙනි",
        "වායුවක් තාප හුවමාරුවකින් තොරව ප්‍රසාරණය වී සිසිල් වීම Adiabatic Cooling නම් වේ."),
      q(t, "අර්ධ ශුෂ්ක සාරවත් ගොඩබිම් මතුපිට ක්‍රමයෙන් නිසරු වැලි කාන්තාර බවට පත්වීමේ ක්‍රියාවලිය කුමක්ද?",
        "කාන්තාරීකරණය (Desertification)", "ග්ලැසියරකරණය (Glaciation)", "නාගරීකරණය (Urbanization)", "සුපෝෂණය (Eutrophication)",
        "අධික තෘණ උලා කෑම, වන විනාශය හා නියඟය නිසා අර්ධ ශුෂ්ක සාරවත් බිම් කාන්තාර බවට පත්වීම කාන්තාරීකරණයයි."),
      q(t, "අප්‍රිකාවේ සහාරා කාන්තාරයට දකුණින් පිහිටි, කාන්තාරීකරණයට දැඩි ලෙස ගොදුරු වන සංක්‍රමණික කලාපය කුමක්ද?",
        "සහෙල් කලාපය (The Sahel)", "කොංගෝ ගංගා ද්‍රෝණිය (Congo Basin)", "වික්ටෝරියා විල ආශ්‍රිත ප්‍රදේශය", "නයිල් ගංගා ඩෙල්ටා කලාපය",
        "සහෙල් කලාපයේ වනාන්තර හරිත පවුරක් (Great Green Wall) මගින් කාන්තාර පැතිරීම පාලනය කිරීමට උත්සාහ කෙරේ."),
      q(t, "නිවර්තන සුළි සුළංවලට ඉන්දියන් සාගරයේදී හා බටහිර පැසිෆික් සාගරයේදී පිළිවෙළින් භාවිත කරන නම් මොනවාද?",
        "චක්‍රවාත (Cyclones) සහ ටයිෆූන් (Typhoons)", "ටෝනේඩෝ (Tornadoes) සහ බ්ලිසාර්ඩ් (Blizzards)", "මිස්ට්‍රල් (Mistral) සහ ෆෝන් (Föhn)", "හර්මැටන් (Harmattan) සහ චිනූක් (Chinook)",
        "අත්ලාන්තික් හා ඊසාන පැසිෆික් හි Hurricanes ලෙසත්, ඕස්ට්‍රේලියාවේ Willy-willies ලෙසත් හැඳින්වේ."),
      q(t, "ටෝනේඩෝවක් (Tornado) සහ නිවර්තන සුළි සුළඟක් (Cyclone) අතර ඇති ප්‍රධාන වෙනස කුමක්ද?",
        "ටෝනේඩෝවක් කුඩා විෂ්කම්භයකින් යුක්තව ගොඩබිම මත කෙටි වේලාවක් පැවතීමයි", "ටෝනේඩෝ සෑම විටම ගැඹුරු සාගරයේ සති ගණනක් පුරා ගමන් කරමින් පැවතීමයි", "නිවර්තන සුළි සුළං මීටර් කිහිපයක පුනීලයක් ලෙස ගොඩබිමේ පමණක් හටගැනීමයි", "ටෝනේඩෝ සහ නිවර්තන සුළි සුළං යන දෙකම ප්‍රමාණයෙන් හා කාලසීමාවෙන් සමාන වීමයි",
        "ඇමරිකා එක්සත් ජනපදයේ මධ්‍යම තැනිතලාව (Tornado Alley) ටෝනේඩෝ සඳහා ප්‍රසිද්ධය."),
      q(t, "වායුගෝලීය අධ්‍යයනයේදී 'පිණි ලක්ෂ්‍යය' (Dew Point) යනුවෙන් හඳුන්වන්නේ කුමක්ද?",
        "නියත පීඩනයකදී වාතය ජල වාෂ්පවලින් 100% සංතෘප්ත වී ඝනීභවනය ඇරඹෙන උෂ්ණත්වයයි", "සාමාන්‍ය වායුගෝලීය පීඩනයේදී පිරිසිදු ජලය වාෂ්ප වෙමින් උතුරන උෂ්ණත්වයයි", "සාගර මතුපිට ජලය හෝ මිරිදිය ඝන අයිස් බවට මිදෙන්නට පටන් ගන්නා උෂ්ණත්වයයි", "සූර්යයාගේ මතුපිට පෘෂ්ඨයෙන් වායුගෝලයට විකිරණය මුදාහරින උෂ්ණත්වයයි",
        "වායු උෂ්ණත්වය පිණි ලක්ෂ්‍යයට ළඟා වූ විට මීදුම, පින්න හෝ වළාකුළු සෑදීම ඇරඹේ."),
      q(t, "බ්‍රිතාන්‍ය දූපත් හා ජපානය යන රටවල් දෙකෙහිම කාලගුණය සංසන්දනයේදී වැසි සැපයුම ස්ථාවර වීමට බලපාන පොදු සාධකය කුමක්ද?",
        "සාගරවලින් වටවූ දූපත් වීම සහ සාගර දියවැල්වල බලපෑම ලැබීමයි", "විශාල මහාද්වීප අභ්‍යන්තරයේ කාන්තාර මැද පිහිටා තිබීමයි", "හරියටම 0° සමක රේඛාව මත පිහිටා තිබීමයි", "පෘථිවි කබොලේ කිසිදු ගිනිකඳු ක්‍රියාකාරිත්වයක් නොමැති වීමයි",
        "මුහුදු සුළං සහ සාගරික බලපෑම මෙම දූපත් රටවල වර්ෂාපතනයට උපකාරී වේ."),
      q(t, "ගෝලීය කාබන් චක්‍රයේදී මහා පරිමාණ ළැව්ගිනි (Wildfires) මගින් දේශගුණයට සිදුවන ද්විත්ව බලපෑම කුමක්ද?",
        "වනාන්තර කාබන් සිංක් විනාශ වීම සහ ගබඩා වූ කාබන් ඩයොක්සයිඩ් වායුගෝලයට මුදා හැරීම", "වායුගෝලයේ ඔක්සිජන් ප්‍රතිශතය දෙගුණයකින් ඉහළ ගොස් උෂ්ණත්වය අඩු වීම", "අවට මහා සාගරවල මතුපිට ජල උෂ්ණත්වය සැලකිය යුතු ලෙස සිසිල් වීම", "දැවී යන ප්‍රදේශවල වාර්ෂික මෝසම් වර්ෂාපතනය නියතව වැඩි වීම",
        "ඊට අමතරව දැවුණු කළු පෘෂ්ඨයේ ඇල්බෙඩෝව අඩු වී තාප අවශෝෂණය ඉහළ යයි."),
      q(t, "දකුණු ආසියානු කලාපයේ මෝසම් පුරෝකථනය අතිශයින් වැදගත් වන්නේ කුමන අංශය සඳහාද?",
        "කෘෂිකාර්මික වගා කාලසටහන්, ජලාශ කළමනාකරණය හා ජල විදුලි සැලසුම් කිරීමටය", "පෘථිවි කබොලේ හටගන්නා ප්‍රබල භූමිකම්පා සම්පූර්ණයෙන්ම නැවැත්වීමටය", "ගැඹුරු සාගර පතුලෙන් ඛනිජ තෙල් හා ස්වාභාවික වායු කැණීමටය", "සමුද්‍ර නාවික කටයුතු සඳහා සාගර පතුල සිතියම්ගත කිරීමටය",
        "ශ්‍රී ලංකාවේ හා ඉන්දියාවේ යල සහ මහ කන්න අස්වැන්න සෘජුවම මෝසම් වර්ෂාව මත රඳා පවතී."),
      q(t, "කාලගුණ සිතියමක හමුවන 'ප්‍රතිචක්‍රවාත' (Anticyclone) පද්ධතියක ඇති ප්‍රධාන ලක්ෂණය කුමක්ද?",
        "මධ්‍යයේ අධි පීඩනයක් පැවතීම, වාතය පහළ බැසීම සහ පැහැදිලි වියළි කාලගුණයක් පැවතීම", "නිරන්තර විනාශකාරී නිවර්තන සුළි සුළං හා ගංවතුර තත්ත්ව ඇති වීම", "සෑම සවසකම අධික ගිගුරුම් සහිත සංවහන වැසි නොකඩවා ඇද හැළීම", "මධ්‍යයේ සිට උණුසුම් තෙත් වාතය ඉතා වේගයෙන් ඉහළට ගමන් කිරීම",
        "අධි පීඩන කලාපයක වාතය පහළ බසිමින් රත් වන නිසා වළාකුළු සෑදීම වළකී."),
      q(t, "ස්ථානයක මාස 12 ක උෂ්ණත්ව අගයන්ගේ උපරිමය 28°C සහ අවමය 26°C වන අතර වාර්ෂික වර්ෂාව මි.මී. 2,800 ක් නම් එය කුමන දේශගුණයක්ද?",
        "සමක වැසි වනාන්තර දේශගුණය (Equatorial Climate)", "උණුසුම් හා වියළි මධ්‍යධරණී දේශගුණය (Mediterranean)", "උතුරු ධ්‍රැවීය ටුන්ඩ්‍රා දේශගුණය (Tundra Climate)", "අධි ශුෂ්ක උෂ්ණ කාන්තාර දේශගුණය (Hot Desert)",
        "වාර්ෂික උෂ්ණත්ව පරාසය 2°C ක් වැනි කුඩා අගයක් වීම සහ අධික වර්ෂාව සමක දේශගුණයේ සලකුණකි."),
      q(t, "ජනවාරි උෂ්ණත්වය -25°C ක් සහ ජූලි උෂ්ණත්වය +16°C ක් වන උතුරු කැනඩාව හෝ සයිබීරියාව අයත් දේශගුණය කුමක්ද?",
        "උප ආක්ටික් හෙවත් ටයිගා දේශගුණය", "සමක වැසි වනාන්තර දේශගුණය", "නිවර්තන මෝසම් දේශගුණය", "නිවර්තන සැවානා දේශගුණය",
        "උතුරු අර්ධගෝලයේ අධි අක්ෂාංශ මහාද්වීප අභ්‍යන්තරයේ ලෝකයේ විශාලතම වාර්ෂික උෂ්ණත්ව පරාසය පවතී."),
      q(t, "නිරිතදිග මෝසම් වැසි ලැබෙන ශ්‍රී ලංකාවේ තෙත් කලාපීය උප ප්‍රදේශවල ජල උල්පත් දිගු කාලීනව රඳා පැවතීමට උදව් වන භූමි පරිභෝජනය කුමක්ද?",
        "ඝන ස්වාභාවික වනාන්තර හා ජල පෝෂක ආරක්ෂිත කලාප පවත්වා ගැනීම", "නාගරික ප්‍රදේශ පුරා විශාල කොන්ක්‍රීට් රථ ගාල් ඉදිකිරීම", "ගංගා ඉවුරු අසල නීති විරෝධී ලෙස වැලි කැණීම් වළවල් කැපීම", "කඳු බෑවුම්වල විවෘත ගල් කොරි හා පතල් කර්මාන්ත පවත්වා ගැනීම",
        "සිංහරාජය හා හෝර්ටන් තැන්න වැනි වනාන්තර පස තෙතමනය රඳවා උල්පත් පෝෂණය කරයි."),
      q(t, "දේශගුණික විපර්යාස අවම කිරීමේ ක්‍රියාමාර්ග අතර 'හරිත බලශක්ති සංක්‍රාන්තිය' යනුවෙන් අදහස් කරන්නේ කුමක්ද?",
        "ගල් අඟුරු හා ඛනිජ තෙල් වෙනුවට සූර්ය, සුළං හා ජල විදුලියට මාරු වීම", "ජල විදුලි බලාගාර වසා දමා ඩීසල් තාප බලාගාර ඉදිකිරීමට මාරු වීම", "දර ඉන්ධන සඳහා තෙත් කලාපීය ස්වාභාවික වනාන්තර සම්පූර්ණයෙන් කපා දැමීම", "නාගරික ප්‍රවාහන කටයුතු සඳහා පොදු ප්‍රවාහනය නවතා පෞද්ගලික වාහන වැඩි කිරීම",
        "ෆොසිල ඉන්ධන වෙනුවට පුනර්ජනනීය බලශක්ති ප්‍රභවයන් භාවිතය හරිතාගාර වායු විමෝචනය අවම කරයි."),
      q(t, "මධ්‍යම ආසියානු හා උතුරු ඇමරිකානු සෞම්‍ය තෘණ බිම් (Steppes, Prairies) ප්‍රධාන වශයෙන් කුමන නිෂ්පාදන සඳහා ප්‍රසිද්ධද?",
        "තිරිඟු හා බඩඉරිඟු වැනි ධාන්‍ය වගාව සහ වාණිජ ගව පාලනය", "තෙත් කඳුකර දේශගුණයට උචිත තේ සහ රබර් වගාව", "කරදිය වගුරු බිම් ආශ්‍රිත කඩොලාන හා කපු වගාව", "සමුද්‍රාසන්න වෙරළ තීරයේ පොල් සහ කුරුඳු වගාව",
        "චර්නොසෙම් (Chernozem - කළු පස) සෞම්‍ය තෘණ බිම් පොහොසත් ධාන්‍ය වගා බිම් බවට පත් කරයි."),
      q(t, "අධික ජල හිඟයකට මුහුණ දෙන ශුෂ්ක ප්‍රදේශවල කෘෂිකාර්මික කටයුතු සඳහා වඩාත්ම කාර්යක්ෂම ජල සම්පාදන ක්‍රමය කුමක්ද?",
        "ශාක මුල් පද්ධතියට සෘජුවම ජලය සපයන බිංදු ජල සම්පාදන ක්‍රමය", "විවෘත පස් ඇළ මාර්ග හරහා සිදු කරන ගංවතුර ජල සම්පාදන ක්‍රමය", "දැඩි හිරු රශ්මිය පවතින දහවල් කාලයේදී ගුවනින් ජලය ඉසීමේ ක්‍රමය", "වගා බිම් සම්පූර්ණයෙන් යට වන සේ උස් පස් බැමි බැඳීමේ ක්‍රමය",
        "බිංදු ජල සම්පාදනයේදී ජලය සෘජුවම ශාක මුල් පද්ධතියට ලබා දෙන බැවින් වාෂ්පීකරණ නාස්තිය අවම වේ."),
      q(t, "සාගර මතුපිට ජලය ධ්‍රැව ආසන්නයේදී සිසිල් හා ලවණතාවෙන් අධික වී ගැඹුරට ගිලා බැසීමෙන් ක්‍රියාත්මක වන ගෝලීය ප්‍රවාහ පද්ධතිය කුමක්ද?",
        "සාගර ජලයේ උෂ්ණත්වය හා ලවණතාව මත ක්‍රියාත්මක වන ගැඹුරු තාප-ලවණ සංසරණය", "වෙරළ තීරයේ දෛනික උෂ්ණත්ව වෙනස මත හමන ගොඩබිම් හා මුහුදු සුළං පද්ධතිය", "ගොඩබිම ඉහළ කඳුකරයේ සිට මුහුද දක්වා ජලය ගෙන යන ගංගා පෝෂක පද්ධතිය", "පෘථිවි ප්‍රාවරණයේ තාප සංවහන ධාරා මගින් මෙහෙයවන භූ තැටි චලන පද්ධතිය",
        "මෙම ගැඹුරු සාගර සංසරණය සමකයේ සිට ධ්‍රැව දක්වා තාපය බෙදා හැරීමට දිගු කාලීනව උපකාරී වේ."),
      q(t, "වලාකුළු වර්ගීකරණයේදී 'ඇල්ටෝ' (Alto-) යන උපසර්ගයෙන් අදහස් කරන්නේ කුමක්ද?",
        "වායුගෝලයේ මීටර් 2,000 සිට 6,000 දක්වා මධ්‍යම උන්නතාංශයේ පිහිටි වළාකුළු", "පොළොව මතුපිටට ඉතා ආසන්න මීටර් 2,000 ට අඩු පහළ වළාකුළු", "මීටර් 6,000 ට වඩා ඉහළින් අයිස් ස්ඵටිකවලින් සෑදී ඇති උස් වළාකුළු", "ගිනිකඳු පිපිරීමකදී වායුගෝලයට ඉහළ නැගෙන අළු හා දුම් වළාවන්",
        "උදාහරණ ලෙස Altocumulus සහ Altostratus මධ්‍යම මට්ටමේ වළාකුළු වේ."),
      q(t, "පාරජම්බුල කිරණවලින් ජීවීන් ආරක්ෂා කරන ඕසෝන් ස්තරයේ තුනී වීමක් (Ozone Hole) ප්‍රධාන වශයෙන් නිරීක්ෂණය වී ඇත්තේ කුමන ප්‍රදේශයට ඉහළින්ද?",
        "දක්ෂිණ ධ්‍රැවයේ ඇන්ටාක්ටිකා මහාද්වීපයට ඉහළින්", "සමක රේඛාව ආසන්න ඇමසන් වනාන්තරයට ඉහළින්", "ඉන්දියන් සාගරයේ ශ්‍රී ලංකා දූපතට ඉහළින්", "යුරෝපය හා අප්‍රිකාව අතර මධ්‍යධරණී මුහුදට ඉහළින්",
        "දැඩි ධ්‍රැවීය ශීතල තුළ සෑදෙන Stratospheric වළාකුළු CFC ක්ලෝරීන් ප්‍රතික්‍රියා වේගවත් කරයි."),
      q(t, "සෘතුමය වෙනස්කම් සමඟ ශීත හෝ වියළි සෘතුවේදී ජලය ඉතිරි කර ගැනීමට පත්‍ර හලන වනාන්තර (Deciduous Forests) බහුලව පවතින්නේ කොහිද?",
        "මධ්‍ය අක්ෂාංශ සෞම්‍ය කලාපවල සහ නිවර්තන මෝසම් කලාපවල", "වසර පුරා නිරන්තර වැසි ලැබෙන සමක වැසි වනාන්තර කලාපවල", "උත්තර ධ්‍රැවයට ආසන්න අධික ශීතල ටුන්ඩ්‍රා කලාපයේ", "ස්ථිර හිමෙන් වැසුණු ධ්‍රැවීය අයිස් තට්ටු සහිත ප්‍රදේශවල",
        "ශ්‍රී ලංකාවේ වියළි මිශ්‍ර සදාහරිත හා පතනශීලී වනාන්තරද නියඟ සමයේ පත්‍ර හලයි."),
      q(t, "ශ්‍රී ලංකාවේ කාලගුණ විද්‍යා දෙපාර්තමේන්තුවේ ප්‍රධාන කාර්යභාරයක් වන්නේ කුමක්ද?",
        "දෛනික කාලගුණ නිරීක්ෂණ, අනාවැකි නිකුත් කිරීම සහ අධික වැසි හා සුළි සුළං පූර්ව අනතුරු ඇඟවීම් ලබා දීම", "දිවයිනේ භූ විද්‍යාත්මක සමීක්ෂණ සිදු කර ඛනිජ හා වැලි කැණීම් බලපත්‍ර නිකුත් කිරීම", "මධ්‍යම කඳුකරයේ ජලාශවල විදුලි ජනන යන්ත්‍ර ක්‍රියාත්මක කර ජාතික විදුලි බලය බෙදා හැරීම", "වනජීවී රක්ෂිත තුළ වනාන්තර සංරක්ෂණ නීති ක්‍රියාත්මක කර දඩ මුදල් අය කිරීම",
        "1867 දී කාලගුණ නිරීක්ෂණ ආරම්භ කළ මෙම ආයතනය කොළඹ බෞද්ධාලෝක මාවතේ පිහිටා ඇත."),
      q(t, "වායු පීඩන සිතියමක 'රිජ්' (Ridge) යනුවෙන් හඳුන්වන්නේ කුමක්ද?",
        "අධි පීඩන පද්ධතියකින් පිටතට දිගු වූ දිවක් වැනි අධි පීඩන තීරුව", "අඩු පීඩන පද්ධතියකින් පිටතට දිගු වූ අඩු පීඩන නිම්න තීරුව", "නිවර්තන සුළි සුළඟක මධ්‍යයේ පවතින සන්සුන් අඩු පීඩන ඇස", "සිතියමක සමාන උන්නතාංශ ස්ථාන යා කරමින් අඳින සමෝච්ච රේඛාව",
        "ඊට ප්‍රතිවිරුද්ධව අඩු පීඩන ප්‍රදේශයකින් දිගු වන තීරුව 'Trough' (අගාධය) නම් වේ."),
      q(t, "ග්‍රීෂ්ම මෝසම් ආරම්භයේදී ශ්‍රී ලංකාවේ හා ඉන්දියාවේ වියළි කාලගුණය හදිසියේම තද ගිගුරුම් වැසි බවට පෙරළීම හඳුන්වන්නේ කෙසේද?",
        "මෝසම් පිපිරීම (Burst of the Monsoon)", "වැසි මුවා කලාපය (Rain Shadow)", "කච්චාන් වියළි සුළඟ (Kachchan Wind)", "අන්තර් ග්ලැසියර සමය (Interglacial Period)",
        "මැයි මස අගදී මුහුදු සුළං වේගවත්ව නිරිතදිගින් ඇතුළු වීම මෝසම් පිපිරීමයි."),
      q(t, "වායුගෝලයේ කාබන් ඩයොක්සයිඩ් (CO2) සාන්ද්‍රණය කාර්මික විප්ලවයට පෙර තිබූ 280 ppm සිට වර්තමානයේ කොපමණ අගයක් දක්වා ඉහළ ගොස් ඇත්ද?",
        "මිලියනයකට කොටස් 420 (420 ppm) ඉක්මවූ මට්ටමකට", "මිලියනයකට කොටස් 150 (150 ppm) පමණ අගයකට", "මිලියනයකට කොටස් 280 (280 ppm) මට්ටමේම ස්ථාවරව", "මිලියනයකට කොටස් 900 (900 ppm) ඉක්මවූ මට්ටමකට",
        "හවායි හි Mauna Loa නිරීක්ෂණාගාරයේ Keeling Curve මගින් මෙම අඛණ්ඩ ඉහළ යාම සටහන් කෙරේ."),
      q(t, "නිවර්තන වෙරළබඩ උණුසුම් තෙත් ප්‍රදේශවල වඩදිය බාදියට හසුවන කලපු හා මෝය ආශ්‍රිතව වැඩෙන සුවිශේෂී වනාන්තර පද්ධතිය කුමක්ද?",
        "ලවණතාවට ඔරොත්තු දෙන කඩොලාන වනාන්තර (Mangrove Forests)", "උතුරු සෞම්‍ය කලාපයේ කේතුධර ටයිගා වනාන්තර", "ශීත හේමන්ත දේශගුණයට අයත් මධ්‍යධරණී ලඳු කැලෑ", "මහාද්වීප අභ්‍යන්තරයේ පිහිටි සෞම්‍ය ප්‍රේරි තෘණ බිම්",
        "ලවණතාවට ඔරොත්තු දෙන කඩොලාන ශාක වෙරළ ඛාදනය හා සුනාමි බලපෑම් අවම කරයි."),
      q(t, "විශාල නගරවල වාහන දුමාරය සහ හිරු එළියේ රසායනික ප්‍රතික්‍රියා මගින් නිර්මාණය වන දූෂිත මීදුම හඳුන්වන්නේ කුමක් ලෙසද?",
        "ප්‍රකාශ රසායනික ධූමිකාව (Photochemical Smog)", "රාත්‍රී විකිරණ සිසිලන මීදුම (Radiation Fog)", "ධ්‍රැවීය අයිස් ස්ඵටික මීදුම (Ice Fog)", "සාගර අභිවහන මුහුදු මීදුම (Advection Fog)",
        "නයිට්‍රජන් ඔක්සයිඩ් හා වාෂ්පශීලී කාබනික සංයෝග UV කිරණ සමඟ ප්‍රතික්‍රියා කර භූමි මට්ටමේ ඕසෝන් සාදයි."),
      q(t, "ශ්‍රී ලංකාවේ කඳුකර කලාපයේ (නුවරඑළිය වැනි) සාමාන්‍ය වාර්ෂික උෂ්ණත්වය පහතරට කොළඹට වඩා 10°C–12°C කින් පමණ අඩු වීමට ප්‍රධාන හේතුව කුමක්ද?",
        "මුහුදු මට්ටමේ සිට මීටර් 1,800 කට වැඩි ඉහළ උන්නතාංශයක පිහිටීම", "උතුරේ සිට දකුණට විහිදෙන විශාල අක්ෂාංශ අන්තරයක පිහිටීම", "මධ්‍යම කඳුකරය වටා ගලා යන සීතල සාගර දියවැල්වල බලපෑම", "උතුරු ආසියාවේ සිට හමා එන අධික ශීතල කාන්තාර සුළං ප්‍රවාහ",
        "ශ්‍රී ලංකාව කුඩා දූපතක් බැවින් උතුර-දකුණ අක්ෂාංශ වෙනසට වඩා උන්නතාංශය උෂ්ණත්වය පාලනය කරයි."),
      q(t, "දේශගුණික ප්‍රස්තාරයක යම් නගරයක ජූලි මාසයේ උෂ්ණත්වය අවම (+6°C) සහ ජනවාරි උෂ්ණත්වය උපරිම (+24°C) නම් එම නගරය පිහිටන්නේ කොහිද?",
        "දකුණු අර්ධගෝලයේ සෞම්‍ය කලාපයේ (Southern Hemisphere)", "උතුරු අර්ධගෝලයේ සෞම්‍ය කලාපයේ (Northern Hemisphere)", "ස්ථිර හිම වැස්මක් සහිත උත්තර ධ්‍රැව වෘත්තයේ", "සෘතු වෙනසක් නොමැති සමක රේඛාව මත සෘජුවම",
        "ජූනි-අගෝස්තු ශීතල සහ දෙසැම්බර්-පෙබරවාරි උණුසුම් වීම දකුණු අර්ධගෝලයේ ලක්ෂණයකි."),
      q(t, "සූර්ය ශක්තිය වැඩිපුරම පරාවර්තනය කර ගෝලීය සිසිල් වීමට දායක වන වායුගෝලීය ද්‍රව්‍යයක් වන්නේ කුමක්ද?",
        "ගිනිකඳු පිපිරීම්වලින් ඉහළ වායුගෝලයට එක්වන සල්ෆේට් අංශු සහ ඝන පහළ වළාකුළු", "වගුරු බිම් හා ගව පාලනයෙන් වායුගෝලයට එක්වන ප්‍රබල මීතේන් වායුව", "ශීතකරණ හා වායු සමීකරණ මගින් මුදා හරින ක්ලෝරොෆ්ලුවොරොකාබන් වායුව", "පොසිල ඉන්ධන අසම්පූර්ණ දහනයෙන් හිම මත තැන්පත් වන කළු දැලි අංශු",
        "1991 පිනාටුබෝ ගිනිකඳු පිපිරීමෙන් පසු ගෝලීය උෂ්ණත්වය තාවකාලිකව 0.5°C කින් පහත වැටුණි."),
      q(t, "නිවර්තන තෙත් හා වියළි කලාපවල ඇති වන සවානා තණබිම් දකුණු ඇමරිකාවේදී හැඳින්වෙන ප්‍රකට කලාපීය නාමයන් යුගලය කුමක්ද?",
        "වෙනිසියුලාවේ ලැනෝස් (Llanos) සහ බ්‍රසීලයේ කැම්පෝස් (Campos)", "උතුරු ඇමරිකාවේ ප්‍රේරි (Prairies) සහ යුරේසියාවේ ස්ටෙප් (Steppe)", "උතුරු අර්ධගෝලයේ ටයිගා (Taiga) සහ ආක්ටික් ටුන්ඩ්‍රා (Tundra)", "ඕස්ට්‍රේලියාවේ ඩවුන්ස් (Downs) සහ දකුණු අප්‍රිකාවේ වෙල්ඩ් (Veld)",
        "සෞම්‍ය තෘණ බිම් උතුරු ඇමරිකාවේ Prairies, ආර්ජන්ටිනාවේ Pampas, දකුණු අප්‍රිකාවේ Veld හා ඕස්ට්‍රේලියාවේ Downs නම් වේ."),
      q(t, "දේශගුණ විද්‍යාත්මකව 'දේශගුණික සරණාගතයින්' (Climate Refugees) යනුවෙන් හඳුන්වන්නේ කවුරුන්ද?",
        "මුහුදු මට්ටම ඉහළ යාම, දැඩි නියඟය හෝ කාන්තාරීකරණය නිසා සිය නිජබිම් අතහැර සංක්‍රමණය වන ජනතාව", "වෙනත් රටවල දේශගුණය අධ්‍යයනය කිරීම සඳහා කෙටි කලකට පැමිණෙන භූගෝල විද්‍යා පර්යේෂකයින්", "ශීත සෘතුව මඟහැර උණුසුම් නිවර්තන වෙරළ තීරවල නිවාඩු ගත කිරීමට පැමිණෙන විදේශ සංචාරකයින්", "නව රැකියා හා උසස් අධ්‍යාපන අවස්ථා සොයා ග්‍රාමීය ප්‍රදේශවල සිට නගරවලට සංක්‍රමණය වන ශ්‍රමිකයින්",
        "ටුවාලු, කිරිබාති වැනි පහත් කොරල් දූපත් රටවල වැසියන් මේ අවදානමට මුහුණ දී සිටී."),
      q(t, "ග්ලැසියර දියවීම සහ සාගර ජලයේ තාප ප්‍රසාරණය හේතුවෙන් ලොව පුරා මුහුදු මට්ටම පොදුවේ ඉහළ යාම හඳුන්වන්නේ කෙසේද?",
        "සාගර ජල පරිමාව වැඩි වීමෙන් සිදුවන ගෝලීය මුහුදු මට්ටම ඉහළ යාම", "භූ කම්පනයක් නිසා එක් වෙරළබඩ ගොඩබිමක් පමණක් පහළට ගිලා බැසීම", "වැසි සමයේදී ගංගා ඉවුරු පිටාර ගලා පහත් බිම් තාවකාලිකව යට වීම", "සාගර පතුලේ නායයෑමක් නිසා ක්ෂණිකව ඇති වන සුනාමි උදම් රළ නැගීම",
        "ග්ලැසියර දියවීම සහ සාගර ජලයේ තාප ප්‍රසාරණය ගෝලීය මුහුදු මට්ටම ඉහළ යාමට ප්‍රධාන හේතු වේ."),
      q(t, "පෘථිවි වායුගෝලයේ ස්ථිර වායූන්ට අමතරව ස්ථානය හා කාලය අනුව 0% සිට 4% දක්වා වැඩිම විචල්‍යතාවක් පෙන්වන වායුව කුමක්ද?",
        "ජල වාෂ්ප (Water Vapour)", "නයිට්‍රජන් (Nitrogen)", "ඔක්සිජන් (Oxygen)", "ආගන් (Argon)",
        "ජල වාෂ්ප ස්වභාවික ප්‍රබලතම හරිතාගාර වායුව වන අතර එය සියලු වැසි හා කුණාටු ඇති කරයි."),
      q(t, "මුහුදෙන් දුරස්ථ මහාද්වීප මැද පිහිටි ප්‍රදේශවල ග්‍රීෂ්ම හා ශීත උෂ්ණත්ව විචල්‍යතාව වැඩි වීම හඳුන්වන්නේ කුමන සංකල්පයෙන්ද?",
        "මහාද්වීපික බලපෑම (Continentality)", "සාගරික මෘදු බලපෑම (Maritime Effect)", "නාගරික තාප දූපත් බලපෑම (Urban Heat Island)", "උන්නතාංශ පාලන බලපෑම (Altitude Effect)",
        "සාගරයේ සමතුලිත බලපෑම නොමැති නිසා මොංගෝලියාවේ උලාන්බාටර් නගරයේ ග්‍රීෂ්ම-ශීත වෙනස අතිමහත්ය."),
      q(t, "සුළඟේ දිශාව හා ප්‍රතිශත වාර ගණන දැක්වීම සඳහා කාලගුණ විද්‍යාවේදී භාවිත කරන රූපසටහන කුමක්ද?",
        "සුළං රෝස සටහන (Wind Rose Diagram)", "ගංගා ජල ප්‍රවාහ සටහන (Hydrograph)", "ජනගහන පිරමීඩ සටහන (Population Pyramid)", "දේශගුණික තීරු සටහන (Climograph)",
        "Wind Rose මගින් ගුවන් තොටුපළ ධාවන පථ සැලසුම් කිරීමේදී ප්‍රමුඛ සුළං දිශාව තීරණය කෙරේ."),
      q(t, "ශ්‍රී ලංකාවේ තෙත් කලාපීය පහතරට හා කඳුකර වනාන්තරවල ශාක විවිධත්වය වියළි කලාපයට වඩා ඉහළ වීමට ප්‍රධාන දේශගුණික හේතුව කුමක්ද?",
        "වසර පුරා ඉහළ හා සමතුලිත වර්ෂාපතනයක් හා විවිධ උන්නතාංශ උෂ්ණත්ව කලාප පැවතීම", "වියළි සමයේදී වෙරළබඩ සුළං මගින් පසට අධික ලවණ සංයෝග එකතු වීම", "වසර පුරා නොකඩවා දැඩි හිම පතනයක් සහ අඩු හිරු එළියක් පැවතීම", "වර්ෂාව නොමැති කාලවලදී භූගත ජල මට්ටම මතුපිටට පැමිණ පස ජලයෙන් යට වීම",
        "ඒකදේශික (Endemic) ශාක හා සත්ත්ව විශේෂ බහුතරයක් ශ්‍රී ලංකාවේ නිරිතදිග තෙත් කලාපයේ වෙසෙති."),
      q(t, "කාලගුණ මධ්‍යස්ථානයේ සම්මත වර්ෂා මානය මගින් යම් දිනයක ලැබුණු වර්ෂාපතන ප්‍රමාණය මනිනු ලබන ඒකකය කුමක්ද?",
        "මිලිමීටර් (mm) හෝ අඟල්", "ග්‍රෑම් (g) හෝ කිලෝග්‍රෑම්", "හෙක්ටොපැස්කල් (hPa) හෝ මිලිබාර්", "නොට්ස් (Knots) හෝ පැයට කිලෝමීටර්",
        "වර්ෂාපතනය මි.මී. 10 ක් යනු පෘෂ්ඨය මත වාෂ්ප වීමෙන් හා ගලා යාමෙන් තොරව මි.මී. 10 ක ගැඹුරට ජලය රැඳීමයි."),
      q(t, "වාතයේ ගුණාත්මකභාවය පහළ බැසීමට හා ශ්වසන රෝග ඇති වීමට බලපාන ඉතා කුඩා අංශුමය ද්‍රව්‍ය (Particulate Matter) හඳුන්වන්නේ කෙසේද?",
        "PM 2.5 සහ PM 10 අංශුමය ද්‍රව්‍ය", "pH 7 උදාසීන ජල අංශු", "UV-A පාරජම්බුල කිරණ", "CFC-12 ශීතකාරක වායු",
        "මයික්‍රොමීටර් 2.5 ට අඩු PM2.5 අංශු පෙනහළු ගැඹුරට ඇතුළු වී ශ්වසන රෝග ඇති කරයි."),
      q(t, "හරිතාගාර වායු විමෝචනය අවම කර ගෝලීය උෂ්ණත්වය පාලනය කිරීමේදී 'ශුද්ධ ශුන්‍ය විමෝචනය' (Net Zero) යන්නෙන් අදහස් කරන්නේ කුමක්ද?",
        "වායුගෝලයට මුදා හරින හරිතාගාර වායු ප්‍රමාණය, වායුගෝලයෙන් ඉවත් කරන ප්‍රමාණයට සමාන කිරීම", "ලෝකයේ සියලුම විදුලි බලාගාර හා ප්‍රවාහන සේවා සම්පූර්ණයෙන්ම නතර කර දැමීම", "සියලුම කෘෂිකාර්මික කටයුතු හා කර්මාන්තශාලා නිෂ්පාදන වහාම වසා දැමීම", "සූර්ය පැනල සහ සුළං විදුලි බලාගාර භාවිතය නීතියෙන් සම්පූර්ණයෙන් තහනම් කිරීම",
        "විමෝචන හැකිතාක් අඩු කර ඉතිරි කොටස වනාන්තර හෝ කාබන් ග්‍රහණ තාක්ෂණයෙන් තුලනය කිරීම Net Zero වේ."),
      q(t, "සාගර ආම්ලීකරණය (Ocean Acidification) සිදු වන්නේ වායුගෝලයේ අධික කුමන වායුව සාගර ජලයේ දියවීම නිසාද?",
        "කාබන් ඩයොක්සයිඩ් (CO2) දියවී කාබොනික් අම්ලය සෑදීමෙන්", "නයිට්‍රජන් (N2) වායුව සාගර මතුපිට ජලයේ අධික ලෙස දියවීමෙන්", "ඔක්සිජන් (O2) වායුව සාගර පතුලේ ශාක ප්ලවාංග මගින් නිපදවීමෙන්", "ආගන් (Argon) වායුව සාගර ලවණ අංශු සමඟ ප්‍රතික්‍රියා කිරීමෙන්",
        "සාගර pH අගය අඩුවීම කොරල්පර හා කවචමය සාගර ජීවීන්ගේ කැල්සියම් කාබනේට් කවච විනාශ කරයි."),
      q(t, "ගොඩබිම් සුළං හා මුහුදු සුළංවලට සමානව මහා පරිමාණ මෝසම් සුළං පද්ධති ඇති වීමේ මූලික භෞතික හේතුව කුමක්ද?",
        "ගොඩබිම හා සාගර අතර සෘතුමය වශයෙන් ඇතිවන අසමාන තාපනය හා පීඩන අන්තරය", "චන්ද්‍රයාගේ සහ සූර්යයාගේ ගුරුත්වාකර්ෂණ බලය නිසා ඇතිවන වඩදිය චලනය", "සාගර පතුලේ පිහිටි භූ තැටි එකිනෙක ගැටීමෙන් සිදුවන කම්පන ශක්තිය", "ධ්‍රැව කලාපවලින් ග්ලැසියර අයිස් කඳු දියවී සාගරයට එකතු වීම",
        "එබැවින් මෝසම් සුළං සෘතුමය වශයෙන් විශාල පරිමාණයේ ගොඩබිම්-මුහුදු සුළං ලෙස හැඳින්විය හැක."),
      q(t, "උතුරු යුරෝපය, කැනඩාව හා උතුරු ඇමරිකාව වැනි සෞම්‍ය කලාපීය රටවල සෘතු 4 පිළිවෙළින් කුමක්ද?",
        "වසන්ත, ග්‍රීෂ්ම, සරත් සහ ශීත සෘතුව", "තෙත්, වියළි, උණුසුම් සහ හිම සෘතුව", "නිරිත මෝසම්, ඊසාන මෝසම් සහ අන්තර් මෝසම්", "පූර්ව ගිම්හාන, මධ්‍ය ගිම්හාන සහ කුණාටු සෘතුව",
        "පෘථිවි අක්ෂයේ 23.5° ඇලවීම නිසා සෞම්‍ය කලාපයේ සෘතු හතර පැහැදිලිව වෙනස් වේ."),
      q(t, "විශාල ජලාශ හා වැව් ඉදිකිරීම නිසා ඒ අවට ප්‍රදේශයේ ක්ෂුද්‍ර දේශගුණයට (Microclimate) ඇති වන සාමාන්‍ය බලපෑම කුමක්ද?",
        "වායු ආර්ද්‍රතාව සුළු වශයෙන් ඉහළ ගොස් අධික දිවා උෂ්ණත්ව අන්තයන් මෘදු වීම", "ජලාශය අවට වාතය සම්පූර්ණයෙන් වියළී ගොස් කාන්තාර පරිසරයක් බිහි වීම", "දිවයිනේ පහතරට ප්‍රදේශවල පවා වසර පුරා අඛණ්ඩ හිම පතනයක් ඇති වීම", "ජලාශය ඉහළ වායු පීඩනය ශුන්‍ය අගයකට පහත වැටී සුළං හමන දිශාව නතර වීම",
        "ජලයේ තාප ධාරිතාව නිසා විශාල ජලාශ අවට පරිසරය සිසිල් හා තෙත් ස්වභාවයක් ගනී."),
      q(t, "භූගෝල විද්‍යාවේදී 'අන්තර් නිවර්තන අභිසාරී කලාපය' (ITCZ) වසර පුරා එකම අක්ෂාංශයක නොරැඳී උතුරට හා දකුණට චලනය වන්නේ ඇයි?",
        "සූර්යයාගේ දෘශ්‍ය උතුරු-දකුණු චලනය සමඟ උපරිම තාපන කලාපය මාරු වන බැවින්", "චන්ද්‍රයා පෘථිවිය වටා පරිභ්‍රමණය වීමේදී වඩදිය බලය වෙනස් වන බැවින්", "මධ්‍යම ආසියාවේ හිමාල කඳු වැටියේ භූ කම්පන සෘතු අනුව වෙනස් වන බැවින්", "ලෝකයේ ප්‍රධාන ගංගාවල ජල ප්‍රවාහය ශීත සෘතුවේදී අඩු වන බැවින්",
        "ජූලි මාසයේදී ITCZ ආසියාව හරහා 20°N පමණ දක්වා ඉහළ නැග මෝසම් ආකර්ෂණයට දායක වේ."),
      q(t, "ඉන්දියන් සාගරයේ කාලගුණයට බලපාන 'ඉන්දියන් සාගර ද්වි-ධ්‍රැවය' (Indian Ocean Dipole - IOD) ධනාත්මක අවධියේදී සිදුවන්නේ කුමක්ද?",
        "බටහිර ඉන්දියන් සාගරය උණුසුම් වී ශ්‍රී ලංකාවට හා නැගෙනහිර අප්‍රිකාවට වැඩි වැසි ලැබීම", "ඉන්දියන් සාගරයේ මතුපිට ජලය සම්පූර්ණයෙන්ම මිදී ධ්‍රැවීය අයිස් තට්ටුවක් සෑදීම", "නිරිතදිග හා ඊසානදිග මෝසම් සුළං දෙකම වසර කිහිපයකට සම්පූර්ණයෙන්ම නැවතී යාම", "නැගෙනහිර පැසිෆික් සාගරයේ ජල උෂ්ණත්වය පහත බැස දකුණු ඇමරිකාවේ ගංගා සිඳී යාම",
        "ධනාත්මක IOD මගින් ශ්‍රී ලංකාවේ ඔක්තෝබර්–නොවැම්බර් දෙවන අන්තර් මෝසම් වැසි තීව්‍ර කළ හැක."),
      q(t, "ගෝලීය දේශගුණික කලාප අතරින් වැඩිම ජෛව විවිධත්වයක් (Biodiversity) දක්නට ලැබෙන්නේ කුමන කලාපයේද?",
        "නිවර්තන සමක වැසි වනාන්තර කලාපයේ (Tropical Rainforests)", "ආක්ටික් හා ඇල්පයින් ටුන්ඩ්‍රා කලාපයේ (Tundra)", "උප නිවර්තන ශුෂ්ක කාන්තාර කලාපයේ (Hot Deserts)", "ස්ථිර ධ්‍රැවීය අයිස් තට්ටු කලාපයේ (Polar Ice Caps)",
        "පෘථිවි ගොඩබිමෙන් 6% ක් පමණ වුවද ලෝකයේ ගොඩබිම් ජීවී විශේෂවලින් 50% කට වඩා සමක වනාන්තරවල වෙසෙති."),
      q(t, "නිවර්තන සුළි කුණාටුවක අවදානම ඇති වෙරළබඩ ප්‍රදේශයක ගොඩබිමට සිදුවන ප්‍රධානම ජල ආශ්‍රිත විනාශය කුමක්ද?",
        "කුණාටු උදම් රළ නැගීම (Storm Surge) සහ අධික ගංවතුර", "සාගර පතුලේ ගිනිකඳු පිපිරීමෙන් ඇතිවන ලාවා ගැලීම", "අධික ශීතල නිසා වෙරළ තීරයේ හටගන්නා හිම කුණාටු", "වෙරළබඩ ගොඩබිම් භූමිය විශාල වශයෙන් ඉරිතැලී ගිලා බැසීම",
        "තද සුළං හා අඩු පීඩනය නිසා මුහුදු ජලය විශාල ලෙස ගොඩබිමට තල්ලු වීම Storm Surge නම් වේ."),
      q(t, "වායුගෝලයේ වර්ෂාපතනය, හිම, හිම කැට සහ මිදුණු වැසි (Sleet) යන සියල්ල පොදුවේ හඳුන්වන්නේ කුමන නමකින්ද?",
        "වර්ෂණය (Precipitation)", "වාෂ්පීකරණය (Evaporation)", "උත්ස්වේදනය (Transpiration)", "ඝනීභවනය (Condensation)",
        "වළාකුළුවලින් ද්‍රව හෝ ඝන ආකාරයෙන් පෘථිවි පෘෂ්ඨයට වැටෙන සියලු ජල රූප වර්ෂණය නම් වේ."),
      q(t, "ස්ටීවන්සන් ආවරණය පොළොවෙන් මීටර් 1.2 ක් ඉහළින් කකුල් මත සවි කරන්නේ ඇයි?",
        "පොළොව මතුපිට අධික තාප විකිරණයේ හා වැසි ජල ඉසීමේ සෘජු බලපෑම වළක්වා ගැනීමට", "සමක කලාපයේ පස තුළ වෙසෙන කෘමීන්ගෙන් උෂ්ණත්වමාන ආරක්ෂා කර ගැනීමට", "වඩා වැඩි සුළං වේගයක් ලබා ගෙන සුළං මානය ක්‍රියාත්මක කිරීමට පහසු වීමට", "රාත්‍රී කාලයේදී උපකරණ තුළ අයිස් ස්ඵටික සෑදීම ඉක්මන් කර ගැනීමට",
        "ලෝක කාලගුණ විද්‍යා සංවිධානයේ සම්මතය අනුව තණකොළ පිට්ටනියක මීටර් 1.2–1.5 උසින් උෂ්ණත්වය මනී."),
      q(t, "කාලගුණ මධ්‍යස්ථානයක වර්ෂා මානයේ (Rain Gauge) ශංකුවක හැඩැති පුනීලයක් යොදා ඇත්තේ ඇයි?",
        "වැසි ජලය ඇතුළු වූ පසු හිරු එළියෙන් හා සුළඟින් වාෂ්ප වීම අවම කිරීමට", "එකතු වන වැසි ජලය මැනීමට පෙර ඉක්මනින් පිටතට ගලා යාමට සැලැස්වීමට", "වැසි සමයේදී වැටෙන දූවිලි හා වැලි අංශු ජලය සමඟ රඳවා තබා ගැනීමට", "සීත කඳුකර ප්‍රදේශවලදී වැටෙන හිම කැට පහසුවෙන් කැඩී යාමට සැලැස්වීමට",
        "වර්ෂා මානය පොළොවට සෙන්ටිමීටර 30 ක් පමණ ඉහළින් සවි කිරීමෙන් පොළොවෙන් ඉසෙන ජල බිඳිති ඇතුළුවීම වළකී."),
      q(t, "වායු පීඩන සිතියම්වල භාවිත කරන 'සමුද්‍ර මට්ටමට සකස් කළ වායු පීඩනය' (Mean Sea Level Pressure) වැදගත් වන්නේ ඇයි?",
        "උන්නතාංශ වෙනස්කම් නිසා ඇතිවන පීඩන වෙනස ඉවත් කර සත්‍ය තිරස් පීඩන රටාව සංසන්දනය කිරීමට", "සිතියමක දැක්වෙන කඳු මුදුන්වල නියම උන්නතාංශය මැන දැක්වීම සඳහා භාවිත කිරීමට", "නාගරික ප්‍රදේශවල දෛනික උෂ්ණත්ව අගයන් කෘත්‍රිමව ඉහළ දැමීම සඳහා යොදා ගැනීමට", "වැසි සමයේදී ගංගාවල පතුලේ ගැඹුර සහ ජල මට්ටම නිවැරදිව මැන බැලීමට",
        "නුවරඑළිය සහ කොළඹ පීඩන දත්ත සෘජුව සැසඳීමට නම් දෙකම සමුද්‍ර මට්ටමට පරිවර්තනය කළ යුතුය."),
      q(t, "උතුරු අර්ධගෝලයේ වෙළඳ සුළං (Northeast Trade Winds) හමා එන නිවැරදි දිශාව කුමක්ද?",
        "ඊසාන දෙසින් නිරිත (සමකය) දෙසට", "නිරිත දෙසින් ඊසාන දෙසට", "දකුණේ සිට උතුර දෙසට", "වයඹ දෙසින් ගිනිකොන දෙසට",
        "සුළං නම් කරනු ලබන්නේ එය හමා එන (Originates from) දිශාව අනුවය."),
      q(t, "දකුණු අර්ධගෝලයේ ගිනිකොන වෙළඳ සුළං (Southeast Trade Winds) හමන්නේ කුමන දිශාවකින් කුමන දිශාවකටද?",
        "ගිනිකොන දෙසින් වයඹ (සමකය) දෙසට", "උතුරේ සිට දකුණ දෙසට", "බටහිර සිට නැගෙනහිර දෙසට", "වයඹ දෙසින් ගිනිකොන දෙසට",
        "මකර නිවර්තන අධි පීඩන කලාපයේ සිට සමකය දෙසට හමා එයි."),
      q(t, "උප නිවර්තන කලාපයේ මහාද්වීපවල නැගෙනහිර වෙරළට වැසි ලැබුණද බටහිර වෙරළ තීරවල කාන්තාර ඇතිවීමට ප්‍රධාන හේතුව කුමක්ද?",
        "බටහිර වෙරළ දිගේ සීතල සාගර දියවැල් ගලා යාම සහ ගොඩබිම සිට හමන වියළි වෙළඳ සුළං", "මහාද්වීපවල නැගෙනහිර වෙරළ තීරයේ කිසිදු කඳු වැටියක් හෝ උස් බිමක් නොමැති වීම", "සූර්යයා සැමවිටම බටහිර වෙරළට පමණක් සෘජුවම පායා අධික තාපයක් ලබා දීම", "මහාද්වීපවල බටහිර වෙරළ ආසන්නයේ නිරන්තරයෙන් ප්‍රබල භූ කම්පන හා ගිනිකඳු පිපිරීම් සිදුවීම",
        "නිදසුන් ලෙස පේරු (හම්බෝල්ට්), බෙන්ගුලා සහ කැනරි සීතල දියවැල් බටහිර වෙරළ කාන්තාර සමඟ බැඳී ඇත."),
      q(t, "ශ්‍රී ලංකාවේ නුවරඑළිය හා බණ්ඩාරවෙල කඳුකර ප්‍රදේශවල වගා කෙරෙන 'උඩරට එළවළු' (කැරට්, ලීක්ස්, ගෝවා) සඳහා හිතකර දේශගුණික සාධකය කුමක්ද?",
        "ඉහළ උන්නතාංශය නිසා පවතින සෞම්‍ය සිසිල් උෂ්ණත්වය (15°C–20°C)", "කඳුකර පසෙහි පවතින අධික සාගරික ලවණතාව සහ ක්ෂාරීය බව", "වසර පුරා පවතින වියළි කාන්තාර උණුසුම සහ දැඩි සුළං ප්‍රවාහ", "ශීත මාසවලදී කඳු මුදුන් මත ඇතිවන අඛණ්ඩ හිම කුණාටු තත්ත්වය",
        "නිවර්තන රටක් තුළ සෞම්‍ය කලාපීය භෝග වැවීමට කඳුකර ක්ෂුද්‍ර දේශගුණය අවස්ථාව සලසයි."),
      q(t, "අධික වර්ෂාවක් පවතින අවස්ථාවක පොළොව මතුපිට ජලය පසට උරා ගැනීමේ වේගයට වඩා වර්ෂාපතන වේගය වැඩි වූ විට කුමක් සිදුවේද?",
        "මතුපිට ජල ගැලීම (Surface Runoff) වැඩි වී පාංශු ඛාදනය හා ගංවතුර ඇති වේ", "පොළොව අභ්‍යන්තරයේ පවතින භූගත ජල මට්ටම සම්පූර්ණයෙන්ම හිඳී වියළී යයි", "මතුපිට මැටි හා ලෝම පස අධික උෂ්ණත්වයෙන් තද ගල් බවට පත් වේ", "වායුගෝලීය තෙතමනය අඩු වී පවතින වර්ෂාව ක්ෂණිකව නතර වේ",
        "නාගරික කොන්ක්‍රීට් පෘෂ්ඨ Infiltration වළක්වා ක්ෂණික ගංවතුර (Flash Floods) වැඩි කරයි."),
      q(t, "කාලගුණ විද්‍යාත්මකව 'දෘශ්‍යතාව' (Visibility) දැඩි ලෙස අඩු කරමින් ගුවන් හා මාර්ග ගමනාගමනයට බාධා කරන සංසිද්ධිය කුමක්ද?",
        "භූමි මට්ටමේ පවතින ඝන මීදුම හා දුම් මීදුම (Fog & Smog)", "කිලෝමීටර් 8 ක් ඉහළ අහසේ ඇති තුනී සිරස් වළාකුළු (Cirrus)", "මීටර් 25,000 ක් ඉහළ අපවර්තී ගෝලයේ පිහිටි ඕසෝන් ස්තරය", "වායුගෝලීය පීඩනය ක්‍රමයෙන් සාමාන්‍ය මට්ටමට ඉහළ යාම",
        "රාත්‍රී උෂ්ණත්ව ප්‍රතිලෝමනය පවතින නිම්න හා වරාය නගරවල ඝන මීදුම බහුලව දැකිය හැක."),
      q(t, "දකුණු ආසියානු කලාපයේ මෝසම් සුළං හට ගැනීමට හේතු වන ටිබෙට් සානුවේ (Tibetan Plateau) ග්‍රීෂ්ම කාර්යභාරය කුමක්ද?",
        "ගිම්හානයේදී අධික ලෙස රත් වී ඉහළ වායුගෝලයේ තාප එන්ජිමක් ලෙස මෝසම් සංසරණය ශක්තිමත් කිරීම", "හිමාල කඳු මුදුන්වල පවතින ග්ලැසියර හිම දියවීම සම්පූර්ණයෙන්ම නැවැත්වීම", "දකුණු අර්ධගෝලයේ සිට හමන වෙළඳ සුළං ආපසු ඇන්ටාක්ටිකාව දෙසට හරවා යැවීම", "වසර පුරාම ඉන්දියන් සාගරයේ මතුපිට ජල උෂ්ණත්වය ශීතල මට්ටමක තබා ගැනීම",
        "මීටර් 4,500 ට වඩා උස ටිබෙට් සානුව මධ්‍යම ආසියානු අඩු පීඩනය ගොඩනැගීමේදී තීරණාත්මක වේ."),
      q(t, "ග්‍රීන්ලන්තය සහ ඇන්ටාක්ටිකාව යන ප්‍රදේශ අයත් වන කෝපන් (Köppen) දේශගුණ කාණ්ඩය කුමක්ද?",
        "ධ්‍රැවීය හිම කැට හා තුහින කලාපය (Polar Ice Cap - EF)", "සෞම්‍ය සමුද්‍රික බටහිර යුරෝපීය කලාපය (Marine West Coast - Cfb)", "නිවර්තන මෝසම් වර්ෂාපතන කලාපය (Tropical Monsoon - Am)", "නිවර්තන තෙත් හා වියළි සැවානා කලාපය (Tropical Savanna - Aw)",
        "EF කලාපයේ සෑම මාසයකම සාමාන්‍ය උෂ්ණත්වය 0°C ට වඩා අඩු බැවින් ස්ථිර අයිස් තට්ටු පවතී."),
      q(t, "අධික සුළං වේගය සහ අඩු වායු පීඩනය නිසා සාගරයේ ඇති වන විනාශකාරී නිවර්තන සුළි සුළං වර්ගීකරණය සඳහා භාවිත කරන පරිමාණය කුමක්ද?",
        "සැෆිර්-සිම්ප්සන් සුළි සුළං පරිමාණය (Saffir-Simpson Scale)", "භූමිකම්පා විශාලත්වය මනින රිච්ටර් පරිමාණය (Richter Scale)", "ඛනිජවල දෘඪතාව මනින මෝස් දෘඪතා පරිමාණය (Mohs Scale)", "අවසාදිත අංශු ප්‍රමාණය මනින වෙන්ට්වර්ත් පරිමාණය (Wentworth Scale)",
        "Category 1 සිට Category 5 දක්වා සුළං වේගය අනුව නිවර්තන සුළි සුළං ශ්‍රේණිගත කෙරේ."),
      q(t, "පෘථිවි ඉතිහාසයේ වර්තමාන ගෝලීය උණුසුම් වීම පිළිබඳ විද්‍යාත්මක දත්ත රැස් කරන ප්‍රධාන ජාත්‍යන්තර ආයතනය කුමක්ද?",
        "දේශගුණික විපර්යාස පිළිබඳ අන්තර් රාජ්‍ය මණ්ඩලය (IPCC)", "ඛනිජ තෙල් අපනයන රටවල ජාත්‍යන්තර සංවිධානය (OPEC)", "ජාත්‍යන්තර නාවික හා සාගර ප්‍රවාහන සංවිධානය (IMO)", "ජාත්‍යන්තර න්‍යෂ්ටික බලශක්ති නියෝජිතායතනය (IAEA)",
        "එක්සත් ජාතීන්ගේ IPCC මණ්ඩලය ගෝලීය දේශගුණ තක්සේරු වාර්තා නිකුත් කරයි."),
      q(t, "සමක වැසි වනාන්තර කපා හෙළීමෙන් පසු පස ඉක්මනින් නිසරු 'ලැටරයිට්' (Laterite) කබොලක් බවට පත්වීමට ප්‍රධාන හේතුව කුමක්ද?",
        "අධික වර්ෂාවෙන් පෝෂක සේදී යාමත් සෘජු හිරු එළියෙන් යකඩ-ඇලුමිනියම් බහුල පස වියළී ඝන වීමත් නිසා", "වනාන්තරය ඉවත් කළ විගස අවට උෂ්ණත්වය පහත බැස පස ඝන හිම තට්ටුවකින් වැසී යන නිසා", "ගස් ඉවත් කිරීමෙන් පසු සාගර ජලය ගොඩබිමට ගලා විත් පසේ ලුණු සාන්ද්‍රණය ඉහළ යන නිසා", "වෘක්ෂලතා විනාශ වූ පසු භූගත ගස් මුල් ප්‍රමාණය වැඩි වී පාෂාණ තට්ටු පුපුරුවා හරින නිසා",
        "Laterization ක්‍රියාවලිය නිවර්තන තෙත් පස්වලට ආවේණික ලක්ෂණයකි."),
      q(t, "දකුණු ශ්‍රී ලංකාවේ මාතර සහ ගාල්ල දිස්ත්‍රික්කවලට මැයි–සැප්තැම්බර් කාලයේ නිරන්තර වැසි ලැබෙන්නේ කුමන සුළං ප්‍රවාහයෙන්ද?",
        "නිරිතදිග මෝසම් සුළං ප්‍රවාහයෙන්", "ඊසානදිග මෝසම් සුළං ප්‍රවාහයෙන්", "නැගෙනහිර කච්චාන් වියළි සුළඟින්", "මධ්‍යධරණී බටහිර සුළං ප්‍රවාහයෙන්",
        "ඉන්දියන් සාගරයේ සිට තෙතමනය රැගෙන එන නිරිතදිග මෝසම මුලින්ම දිවයිනේ නිරිතදිග වෙරළට ඇතුළු වේ."),
      q(t, "දිවා කාලයේ පවතින අධික සූර්ය විකිරණය හමුවේ 'හරිතාගාරයක' (Greenhouse) වීදුරු මෙන් ක්‍රියා කරන වායුගෝලයේ ලක්ෂණය කුමක්ද?",
        "කෙටි තරංග සූර්ය විකිරණයට ඇතුළු වීමට ඉඩ දී පොළොවෙන් පිටවන දිගු තරංග තාප විකිරණය අවහිර කිරීම", "දිවා කාලයේදී පෘථිවියට පැමිණෙන සියලුම හිරු එළිය ඕසෝන් ස්තරයෙන් ආපසු හරවා යැවීම", "පෘථිවි පෘෂ්ඨයෙන් නිකුත් වන සියලු තාප ශක්තිය ධ්‍රැව කලාපවල අයිස් කඳු බවට හැරවීම", "වායුගෝලයේ ඇති නයිට්‍රජන් හා ඔක්සිජන් වායූන් සාගර ජලය තුළට සම්පූර්ණයෙන්ම අවශෝෂණය කිරීම",
        "CO2, CH4, N2O සහ ජල වාෂ්ප දිගු තරංග අධෝරක්ත කිරණ අවශෝෂණය කර නැවත පෘථිවිය දෙසට විකිරණය කරයි."),
      q(t, "නිරිතදිග මෝසම් සමයේදී අම්පාර සහ මඩකලපුව දිස්ත්‍රික්ක වියළිව පවතින අතර පොළොන්නරුව හා ත්‍රිකුණාමලය ප්‍රදේශවල උෂ්ණත්වය ඉහළ යන්නේ ඇයි?",
        "මධ්‍යම කඳුකරයේ වැසි මුවාවේ පිහිටීම සහ පහළ බසින වියළි කච්චාන් සුළඟේ බලපෑම නිසා", "නැගෙනහිර පළාත සමක රේඛාවට බටහිර වෙරළට වඩා ඉතා ආසන්නව පිහිටා තිබීම නිසා", "නැගෙනහිර මුහුදු පතුලේ සක්‍රීය ගිනිකඳු පිහිටා තිබී ජලය උණුසුම් කිරීම නිසා", "පොළොන්නරුව සහ ත්‍රිකුණාමලය ප්‍රදේශ සාගරයෙන් සම්පූර්ණයෙන්ම වෙන්වී කඳු අතර පිහිටීම නිසා",
        "මැයි–සැප්තැම්බර් කාලය නැගෙනහිර වෙරළේ ප්‍රධාන වියළි හා සංචාරක සමයයි."),
      q(t, "පෘථිවි පෘෂ්ඨයේ සම-වර්ෂාපතන රේඛා (Isohyets) ඇඳීමේදී මිනුම් ලබා ගන්නා සම්මත කාලසීමාව සාමාන්‍යයෙන් කුමක්ද?",
        "මාසික හෝ වාර්ෂික සමුච්චිත වර්ෂාපතනය (මි.මී.)", "තත්පරයකදී පොළොවට වැටෙන ක්ෂණික වර්ෂාපතනය", "පැයක කාලය තුළ වෙනස් වන වායු පීඩන අගය", "දෛනිකව සටහන් වන උපරිම සුළං වේගයේ සාමාන්‍යය",
        "වාර්ෂික Isohyet සිතියමකින් රටක තෙත්, අතරමැදි හා වියළි කලාප මායිම් පැහැදිලිව දැකිය හැක."),
      q(t, "වැසි සමයේදී 'ප්‍රභාත හා සන්ධ්‍යා වළාකුළු' වර්ණවත් රතු-තැඹිලි පැහැයෙන් දිස්වීමට හේතු වන වායුගෝලීය ක්‍රියාවලිය කුමක්ද?",
        "හිරු කිරණ වැඩි වායුගෝල දුරක් හරහා එන විට කෙටි නිල් තරංග විසිරී දිගු රතු තරංග ඉතිරි වීම", "සාගර පතුලේ සක්‍රීය ගිනිකඳුවලින් නිකුත් වන ලාවා ආලෝකය වළාකුළු මත පතිත වීම", "අපවර්තී ගෝලයේ පිහිටි ඕසෝන් වායුව හිරු රශ්මිය සමඟ ගැටී දහනය වීම", "ධ්‍රැවීය අයිස් තට්ටුවලින් පරාවර්තනය වන සුදු ආලෝකය සමකය දෙසට ගමන් කිරීම",
        "වායුගෝලයේ දූවිලි හා ජල වාෂ්ප අංශු මෙම ආලෝක විසිරීම තවත් වර්ණවත් කරයි."),
      q(t, "ජපානයේ හොක්කයිඩෝ සිට චීනයේ කඳුකරය හරහා ඇතිවන ශීත මෝසම් සුළං (Winter Monsoon) නිසා නිරීක්ෂණය වන ප්‍රධාන ලක්ෂණය කුමක්ද?",
        "ආසියානු මහාද්වීප අභ්‍යන්තරයෙන් එන සීතල වියළි සුළං ජපන් මුහුද හරහා ගොස් බටහිර ජපානයට හිම ගෙන ඒම", "සමක සාගරයේ සිට උණුසුම් තෙතමනය රැගෙන විත් නැගෙනහිර ආසියාවට අධික මෝසම් වැසි ගෙන ඒම", "දකුණු චීන මුහුදේ උෂ්ණත්වය ඉහළ දමමින් වසරේ ශීත සෘතුව සම්පූර්ණයෙන්ම ඉවත් කර දැමීම", "උතුරු පැසිෆික් සාගරයේ සියලුම සුළං ප්‍රවාහ නතර කර සන්සුන් වායුගෝලයක් නිර්මාණය කිරීම",
        "සයිබීරියානු අධි පීඩනයෙන් හමන ශීත මෝසම ගොඩබිමේ වියළි වුවද සාගරය හරහා යද්දී තෙතමනය උරාගනී."),
      q(t, "විවිධ රටවල වෙරළබඩ නගර හා අභ්‍යන්තර නගර සැසඳීමේදී දෛනික උෂ්ණත්ව පරාසය (Diurnal Temperature Range) වැඩි වන්නේ කොහිද?",
        "මහාද්වීප අභ්‍යන්තරයේ පිහිටි කාන්තාර හා වියළි සානු ප්‍රදේශවල", "සමක කලාපයේ පිහිටි කුඩා දූපත් හා වෙරළබඩ නගරවල", "වඩදිය බාදියට හසුවන වෙරළබඩ කඩොලාන තෙත් බිම් කලාපවල", "වසර පුරා ඝන වළාකුළු පවතින නිවර්තන කඳුකර වැසි වනාන්තරවල",
        "සහරා කාන්තාරයේ දහවල් 45°C සිට රාත්‍රී 5°C දක්වා 40°C ක දෛනික වෙනසක් සිදුවිය හැක."),
      q(t, "භූගෝල විද්‍යාත්මකව 'දේශගුණ සංවේදී ආර්ථික අංශ' අතර ඉහළම අවදානමක් ඇති ක්ෂේත්‍රය කුමක්ද?",
        "වර්ෂාව මත යැපෙන කෘෂිකර්මාන්තය, මිරිදිය ධීවර කර්මාන්තය සහ ජල විදුලි උත්පාදනය", "වායු සමීකරණ කාර්යාල තුළ සිදු කරන පරිගණක මෘදුකාංග නිෂ්පාදන කර්මාන්තය", "නාගරික කර්මාන්තශාලා තුළ ක්‍රියාත්මක වන පොත් හා පුවත්පත් මුද්‍රණ කර්මාන්තය", "භූගත පතල් කැණීම් හරහා සිදු කරන මැණික් හා රන් ආභරණ නිෂ්පාදන කර්මාන්තය",
        "ශ්‍රී ලංකාවේ බලශක්ති හා ආහාර සුරක්ෂිතතාව කාලගුණික විචල්‍යතාවලට දැඩි ලෙස සංවේදී වේ."),
      q(t, "නිවර්තන වර්ෂා වනාන්තරවල වර්ෂා ජලය ගස්වල කඳ හා අතු දිගේ පසට බැසීමේදී පාංශු ඛාදනය වළක්වන ක්‍රියාවලිය කුමක්ද?",
        "වියන් අවහිරණය (Canopy Interception) මගින් වැසි බිඳු වේගය අඩු කිරීම", "මතුපිට ජල ගැලීම (Surface Runoff) වැඩි කර ගංවතුර ඇති කිරීම", "පසෙහි මතුපිට උෂ්ණත්වය ඉහළ දමා ජලය වාෂ්ප කර හැරීම", "වනාන්තර තුළ හමන සුළං වේගය වැඩි කර වැසි බිඳු විසුරුවා හැරීම",
        "බහු-ස්තර වනාන්තර වියන වැසි බිංදුවල චාලක ශක්තිය අඩු කර පස ආරක්ෂා කරයි."),
      q(t, "වායුගෝලීය පීඩන පද්ධති අධ්‍යයනයේදී 'බයිස් බැලොට් නියමය' (Buys Ballot's Law) අනුව උතුරු අර්ධගෝලයේ සුළඟට පිටුපස හරවා සිටගත් විට අඩු පීඩනය පිහිටන්නේ කුමන අතටද?",
        "වම් අත පැත්තට", "දකුණු අත පැත්තට", "සෘජුවම ඉදිරි පැත්තට", "සෘජුවම පිටුපස පැත්තට",
        "කොරියෝලිස් ආචරණය නිසා උතුරු අර්ධගෝලයේදී වම් පසින් අඩු පීඩනයත් දකුණු පසින් අධි පීඩනයත් පිහිටයි."),
      q(t, "සමක කලාපයේ උෂ්ණත්වය අධික වුවද ලෝකයේ ඉහළම වාර්තාගත උෂ්ණත්වයන් (50°C+) සටහන් වන්නේ නිවර්තන ආසන්න කාන්තාරවල මිස සමකයේ නොවන්නේ ඇයි?",
        "සමකයේ නිරන්තර වළාකුළු හා වැසි තාපය සිසිල් කරන අතර කාන්තාරවල පැහැදිලි අහස හා වියළි බව පවතින බැවින්", "සමක කලාපයට වසරේ මාස හයක් පමණ කිසිදු සූර්යාලෝකයක් නොලැබී අඳුරේ පවතින බැවින්", "උප නිවර්තන කාන්තාර ප්‍රදේශ පෘථිවියේ උණුසුම් හරයට වඩාත් ආසන්නයෙන් පිහිටා ඇති බැවින්", "සමක කලාපයේ උස් කඳු වැටි මත වසර පුරාම හිම වැටී පරිසර උෂ්ණත්වය අඩු කරන බැවින්",
        "ලිබියාවේ එල්-අසීසියා සහ ඇමරිකාවේ ඩෙත් වැලි වැනි ස්ථාන උප නිවර්තන අධි පීඩන කලාප ආසන්නයේ පිහිටයි.")
    )
  }
}

